export const calculateDistance = (pos1, pos2) => {
	const deltaX = pos2.x - pos1.x;
	const deltaY = pos2.y - pos1.y;
	const deltaZ = pos2.z - pos1.z;

	const distance = Math.sqrt(deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ);
	return distance;
}

export const calculateStereoPan = (userPosition, soundPosition, forwardVector, stereoMul) => {
	// Calculate vectors from player to sound
	const dx = soundPosition.x - userPosition.x;
	const dy = soundPosition.y - userPosition.y;
	const dz = soundPosition.z - userPosition.z;

	// Calculate the distance between player and sound
	const distance = Math.sqrt(dx * dx + dy * dy + dz * dz);

	// Normalize the forward vector
	const forwardLength = Math.sqrt(forwardVector.x * forwardVector.x + forwardVector.y * forwardVector.y + forwardVector.z * forwardVector.z);
	const forwardX = forwardVector.x / forwardLength;
	const forwardY = forwardVector.y / forwardLength;
	const forwardZ = forwardVector.z / forwardLength;

	// Calculate the dot product of the forward vector and the vector from player to sound
	const dotProduct = (forwardX * dx + forwardY * dy + forwardZ * dz) / distance;

	// Update the StereoPanner based on the dot product
	return dotProduct * stereoMul
}


export const fadeValue = (a, b, duration, type, callback) => {
	let val1, val2;
	let current = a;
	let startTime;

	if (type == 'linear') {
		val1 = Math.sign(b - a);
		val2 = val1 * Math.abs(b - a) / duration;
	} else if (type == 'exponential') {
		val1 = b / a;
		val2 = Math.pow(val1, 1 / duration);
	}

	function animate(timestamp) {
		if (!startTime) startTime = timestamp;
		const elapsed = timestamp - startTime;

		const progress = Math.min(1, elapsed / duration);
		current = type == 'linear' ? (a + val2 * elapsed) : (a * Math.pow(val2, elapsed));

		if (type == 'linear' ? ((val1 === 1 && current >= b) || (val1 === -1 && current <= b) || progress >= 1) : ((b > a && current >= b) || (b < a && current <= b) || progress >= 1)) {
			current = b;
			callback(current, true);
		} else {
			callback(current, false);
			requestAnimationFrame(animate);
		}
	}

	requestAnimationFrame(animate);
}

export const calculateVolume = (position, soundPosition, soundDistance, noLossPercentage, algo) => {
	const distance = calculateDistance(soundPosition, position)
	const maxVolume = 1;
	const minVolume = 0;

	// Calculate the distance beyond which volume reduction starts
	const noLossDistance = soundDistance * noLossPercentage;

	if (distance <= noLossDistance) {
		return 1;
	} else if (distance >= soundDistance) {
		return 0
	} else {
		if (algo == 'sqrt') {
			return Math.sqrt(1 - ((distance - noLossDistance) / (soundDistance - noLossDistance)))
		} else if (algo == 'linear') {
			return (maxVolume - minVolume) * (1 - (distance - noLossDistance) / (soundDistance - noLossDistance)) + minVolume
		} else if (algo == 'exp') {
			return Math.pow((1 - ((distance - noLossDistance) / (soundDistance - noLossDistance))), 2)
		}
	}
}

export function formatTime(time) {
	return time ? Math.floor(time / 60) + ':' + (+time.toFixed(0) % 60).toString().padStart(2, '0') : '0:00'
}

export function formatTime2(time, minString, secondString) {
	return time ? Math.floor(time / 60) + ' ' + minString + ' ' + (+time.toFixed(0) % 60).toString() + ' ' + secondString : '0' + ' ' + minString + ' ' + '0' + ' ' + secondString
}

export function truncate(text, maxLength) {
	if (text.length <= maxLength) {
		return text;
	}
	return text.substring(0, maxLength) + '...';
}

export function uuidToHexColor(uuid) {
	const hexString = uuid.replace(/[^a-fA-F0-9]/g, '');
	const paddedHexString = hexString.padEnd(6, '0');
	const hexColor = paddedHexString.slice(0, 6);
	return `${hexColor}`;
}

export function darkenColor(col, amt) {
	let usePound = false;
	if (col[0] == "#") {
		col = col.slice(1);
		usePound = true;
	}

	const num = parseInt(col, 16);

	let r = (num >> 16) + amt;

	if (r > 255) r = 255;
	else if (r < 0) r = 0;

	let b = ((num >> 8) & 0x00FF) + amt;

	if (b > 255) b = 255;
	else if (b < 0) b = 0;

	let g = (num & 0x0000FF) + amt;

	if (g > 255) g = 255;
	else if (g < 0) g = 0;

	return (usePound ? "#" : "") + (g | (b << 8) | (r << 16)).toString(16);
}

function hashStringToNumber(str: string): number {
	let hash = 0;
	for (let i = 0; i < str.length; i++) {
		hash = str.charCodeAt(i) + ((hash << 5) - hash);
	}
	return hash;
}

