export function uuidToBase64Svg(uuid: string): string {
	if (!uuid) return EMPTY_IMG

	const baseColor = uuidToHexColor(uuid);
	const hexColor = darkenColor(baseColor, 20);
	const hexColor2 = darkenColor(baseColor, 100);
	const darkenedColor = darkenColor(baseColor, 120);

	const hash = hashStringToNumber(uuid);
	const directions = [
		{ x1: "0%", y1: "0%", x2: "100%", y2: "100%" },
		{ x1: "0%", y1: "100%", x2: "100%", y2: "0%" },
		{ x1: "100%", y1: "0%", x2: "0%", y2: "100%" },
		{ x1: "100%", y1: "100%", x2: "0%", y2: "0%" },
	];
	const direction = directions[Math.abs(hash) % directions.length];

	const svg = `
	  <svg xmlns="http://www.w3.org/2000/svg" width="100" height="100" viewBox="0 0 24 24">
		<rect width="100%" height="100%" fill="#000000"/>
		<defs>
			<linearGradient id="grad1" x1="${direction.x1}" y1="${direction.y1}" x2="${direction.x2}" y2="${direction.y2}">
				<stop offset="0%" style="stop-color:#${hexColor};stop-opacity:1" />
				<stop offset="100%" style="stop-color:#${hexColor2};stop-opacity:1" />
			</linearGradient>
		</defs>
      	<rect opacity="0.7" width="100%" height="100%" fill="url(#grad1)"/>
		<path transform="scale(0.5) translate(12, 12)" fill="#${darkenedColor}" d="M3 22a1 1 0 0 1-1-1V3a1 1 0 0 1 2 0v18a1 1 0 0 1-1 1zM15.5 2.134A1 1 0 0 0 14 3v18a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V6.464a1 1 0 0 0-.5-.866l-6-3.464zM9 2a1 1 0 0 0-1 1v18a1 1 0 1 0 2 0V3a1 1 0 0 0-1-1z"/>
	  </svg>
	`;

	return `data:image/svg+xml;base64,${window.btoa(svg)}`;
}

function rgbToGrayscale(rgb) {
	return 0.299 * rgb[0] + 0.587 * rgb[1] + 0.114 * rgb[2];
}

function distanceFromGray(rgb) {
	const grayValue = rgbToGrayscale(rgb);
	const grayRGB = [grayValue, grayValue, grayValue];
	return Math.sqrt(
		Math.pow(rgb[0] - grayRGB[0], 2) +
		Math.pow(rgb[1] - grayRGB[1], 2) +
		Math.pow(rgb[2] - grayRGB[2], 2)
	);
}

export function getBestColor(colors) {
	if (!colors || colors.length == 0) return null

	const distances = colors ? colors.map(color => distanceFromGray(color)) : null;
	const maxDistanceIndex = distances ? distances.indexOf(Math.max(...distances)) : null;
	const colorDiffersMost = colors ? colors[maxDistanceIndex] : null;

	return '#' + colorDiffersMost.map(x => x.toString(16).padStart(2, '0')).join('');
}

export function extractYouTubeVideoId(url) {
	// Regular expressions to match YouTube video IDs
	const patterns = [
		/^https?:\/\/www\.youtube\.com\/watch\?v=([\w\-_]+)/,
		/^https?:\/\/youtube\.com\/watch\?v=([\w\-_]+)/,
		/^https?:\/\/youtu\.be\/([\w\-_]+)/,
		/^https?:\/\/www\.youtube\.com\/embed\/([\w\-_]+)/,
		/^https?:\/\/www\.youtube\.com\/v\/([\w\-_]+)/
	];

	for (const pattern of patterns) {
		const match = url.match(pattern);
		if (match) {
			return match[1];
		}
	}

	return null;
}


