import Icon from "components/Icon";
import { useLocation, useNavigate } from "react-router-dom";

export default function Navigation() {
	const navigate = useNavigate()
	const location = useLocation()

	const isPlaylist = location.pathname.includes('/playlist')
	
	return (
	   <div className={`flex flex-row items-center gap-2 2xl:gap-2 ml-3 2xl:ml-3 ${isPlaylist ? 'text-base-100' : 'text-base-200'}`}>
			<button className={`flex p-1 2xl:p-1.5 rounded-full opacity-100 disabled:opacity-50 ${isPlaylist ? 'bg-[#121212]' : 'bg-[#363636]'}`} onClick={() => navigate(-1)} disabled={!window['navigation'].canGoBack}>
				<Icon name="left" className='h-3 w-3 2xl:h-3.5 2xl:w-3.5' />
			</button>
			<button className={`flex p-1 2xl:p-1.5 rounded-full opacity-100 disabled:opacity-50 ${isPlaylist ? 'bg-[#121212]' : 'bg-[#363636]'}`} onClick={() => navigate(1)} disabled={!window['navigation'].canGoForward}>
				<Icon name="right" className='h-3 w-3 2xl:h-3.5 2xl:w-3.5' />
			</button>
	   </div>
	)
}