import BouncingMarquee from 'components/BouncingMarquee';
import { useCurrentSound, usePlaylists } from 'state/application/hooks';
import { useScript } from 'hooks/useScript';
import { useState } from 'react';
import AddToPlaylist from 'components/AddToPlaylist';
import Icon from 'components/Icon';
import { extractYouTubeVideoId } from 'utils/utils';

const PlayerName = () => {
	const { config, getTranslationKey } = useScript()
	const audio = useCurrentSound()
	const playlists = usePlaylists()
	const [selectedSong, setSelectedSong] = useState(null)
	const [addToPlaylistOpen, setAddToPlaylistOpen] = useState(false)

	function addToList(e) {
		e.stopPropagation();
		const id = extractYouTubeVideoId(audio['url'])
		
		if (id) {
			const song = {
				id: id,
				title: audio['metadata'] ? audio['metadata'].title : '',
				artist: audio['metadata'] ? audio['metadata'].artist : '',
				thumbnail: audio['metadata'] ? audio['metadata'].thumbnail : '',
				duration: audio['maxDuration'] ? audio['maxDuration'] : 0,
				url: audio['url'] ? audio['url'] : 0,
				isExplicit: false
			}
	
			setSelectedSong(song)
			setAddToPlaylistOpen(true)	
		}
	}

	if (!audio) return null


	if (audio && audio['audioStatus'] == 'failed') return (
		<div className='flex flex-col justify-center shadow-inner shadow-2xl overflow-hidden'>
			<div className='text-base-100 text-xs 2xl:text-sm whitespace-nowrap'>
				<BouncingMarquee text={getTranslationKey("errorTextPlayer")} />
				<div className='text-base-400 text-xxs 2xl:text-xs'>
					<BouncingMarquee text={audio['error']} />
				</div>
			</div>
		</div>
	)

	if (audio && audio['audioType'] == 'unknown') return (
		<div className='flex flex-col justify-center shadow-inner shadow-2xl overflow-hidden'>
			<div className='text-base-100 text-xs 2xl:text-sm whitespace-nowrap'>
				<BouncingMarquee text={getTranslationKey("loaderTextPlayer")} />
			</div>
		</div>
	)

	if (audio && audio['audioType'] == 'audio' && audio['metadata']) {
		const id = extractYouTubeVideoId(audio['url'])
		const containsSong = id && playlists && playlists.some(playlist => playlist.songs.findIndex(s => s.id == id) !== -1)

		return (
			<div className='flex flex-row gap-2 2xl:gap-3 overflow-hidden'>
				<div className='flex flex-col justify-center shadow-inner shadow-2xl overflow-hidden'>
					<div className='text-base-100 text-xs 2xl:text-sm whitespace-nowrap'>
						<BouncingMarquee text={audio['metadata']['title'] ? audio['metadata']['title'] : getTranslationKey("loaderTextPlayer")} />
					</div>
		
					{audio['metadata']['artist'] && (
						<div className='text-base-400 text-xxs 2xl:text-xs'>
							<BouncingMarquee text={audio['metadata']['artist']} />
						</div>
					)}
				</div>

				{(config && config.useSQL && id != null) && (
					<button onClick={(e) => addToList(e)} className='block text-base-400 hover:text-base-200'>
						<Icon name={containsSong ? 'circle-check' : 'circle-plus'} className={`h-3.5 w-3.5 2xl:h-4 2xl:w-4 ${containsSong ? 'text-green-500' : 'text-gray-400'}`} />
					</button>
				)}

				<AddToPlaylist song={selectedSong} isOpen={addToPlaylistOpen} setOpen={setAddToPlaylistOpen} />
			</div>
		)
	} 

	if (audio && audio['audioType'] == 'stream' && audio['metadata']) {
		const item = config && config.audioStreams && config.audioStreams.find(o => o.url == audio['url']) ? config.audioStreams.find(o => o.url == audio['url']) : null
		return (
			<div className='flex flex-col justify-center shadow-inner shadow-2xl overflow-hidden'>
				<div className='text-base-100 text-xs 2xl:text-sm whitespace-nowrap'>
					<BouncingMarquee text={item ? item['title'] : audio['metadata']['title']} />
				</div>

				<div className='flex flex-row'>
					<div className='flex flex-row justify-center items-center text-xxs uppercase gap-1.5 w-fit px-1.5 rounded-md bg-[#181818]'>
						<span className='h-2 w-2 rounded-full bg-red-500 animate-pulse'></span>
						<span className='pr-0.5'>{getTranslationKey("liveTagPlayer")}</span>
					</div>
				</div>
			</div>
		)
	}
}

export default PlayerName


