import React, { createContext, useContext, useRef } from 'react';

// Create a context
const DivRefContext = createContext(null);

export const useDivRef = () => useContext(DivRefContext);

export const DivRefProvider = ({ children }) => {
	const divRef = useRef(null);
	return (
		<DivRefContext.Provider value={divRef}>
			{children}
		</DivRefContext.Provider>
	);
};