import { useCurrentId, useCurrentSound } from 'state/application/hooks';
import { useScript } from 'hooks/useScript';
import * as SliderPrimitive from "@radix-ui/react-slider"
import { useEffect, useState } from 'react';
import { fetchNui } from 'utils/fetchNui';
import Icon from 'components/Icon';
import { useNuiEvent } from 'hooks/useNuiEvent';

const PlayerSoundSlider = () => {
	const { config } = useScript()
	const currentId = useCurrentId()
	const audio = useCurrentSound()

	const [mutedVolume, setMutedVolume] = useState(null)
	const [currentVolume, setCurrentVolume] = useState(0)
	const [isVolumeDown, setVolumeDown] = useState(false)


	useNuiEvent<string>('EVO:evo_sound_player:NUI:updateVolume', (data: any) => {
		if (data && data.id === currentId) {
			setCurrentVolume(data.volume)
		}
	})

	useEffect(() => {
		if (config) {
			setCurrentVolume(config.defaultVolume)
		}
	}, [config])

	useEffect(() => {
		if (currentId && audio) {
			setCurrentVolume(audio['volume'])
		}
	// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [audio && audio['volume'], currentId])


	function onVolumePointerDown() {
		if (!currentId) return;

		setVolumeDown(true)
	}

	function onVolumePointerUp() {
		if (!currentId || !audio) return;

		if (isVolumeDown) {
			setTimeout(() => {
				fetchNui('EVO:evo_sound_player:NUI:requestVolume', { id: audio.id, volume: currentVolume })
				setVolumeDown(false)
			}, 100);
		}
	}

	function toggleMute() {
		if (!currentId || !audio) return;
		setVolumeDown(true)

		if (currentVolume > 0) {
			setMutedVolume(currentVolume)
			setCurrentVolume(0)
			fetchNui('EVO:evo_sound_player:NUI:requestVolume', { id: audio.id, volume: 0 })
		} else {
			const newVol = mutedVolume ? mutedVolume : config.defaultVolume
			setCurrentVolume(newVol)
			fetchNui('EVO:evo_sound_player:NUI:requestVolume', { id: audio.id, volume: newVol })
			setMutedVolume(null)
		}
	}

	function renderVolumeIcon(vol) {
		if (vol == 0) {
			return <Icon name="sound-muted" />;
		} else if (vol < 0.33) {
			return <Icon name="sound-low" />;
		} else if (vol < 0.66) {
			return <Icon name="sound-mid" />;
		} else {
			return <Icon name="sound-high" />;
		}
	}

	return (
		<div className='flex flex-row items-center min-w-[120px] gap-1.5'>
			<button onClick={() => toggleMute()} className='w-4 h-4 2xl:h-5 2xl:w-5 fill-base-300'>
				{renderVolumeIcon(currentVolume)}
			</button>

			<SliderPrimitive.Root
				className="relative flex w-full touch-none transition-all select-none items-center group rounded-xl py-2 px-1"
				value={[currentVolume]}
				max={1}
				min={0}
				step={0.01}
				onPointerDown={() => onVolumePointerDown()}
				onPointerUp={() => onVolumePointerUp()}
				onValueChange={(value) => { currentId ? setCurrentVolume(value[0]) : null }}
			>
				<SliderPrimitive.Track className="relative h-[4px] w-full transition-colors grow overflow-hidden rounded-xl bg-[#4d4c4c]">
					<SliderPrimitive.Range className="absolute h-full transition-all group-hover:transition-colors bg-base-100 rounded-xl group-hover:bg-emerald-500 group-hover:[&[data-disabled]]:bg-red-300 [&[data-disabled]]:bg-red-300" />
				</SliderPrimitive.Track>

				<SliderPrimitive.Thumb className="opacity-0 group-hover:opacity-100 [&[data-disabled]]:group-hover:opacity-0 block w-3 h-3 2xl:h-3 2xl:w-3 bg-white rounded-full border-2 border-primary bg-background ring-offset-background transition-all focus-visible:outline-none" />
			</SliderPrimitive.Root>
		</div>
	)
}

export default PlayerSoundSlider


