import { motion, useAnimation, useMotionValue, useMotionValueEvent } from 'framer-motion';
import { useEffect, useRef, useState } from 'react';

const BouncingMarquee = ({ text }) => {
	const controls = useAnimation();
	const [hover, setHover] = useState(false)
	const [mask, setMask] = useState('')
	const [direction, setDirection] = useState('left');
	const [textWidth, setTextWidth] = useState(null);
	const [containerWidth, setContainerWidth] = useState(null);
	const textRef = useRef(null);
	const x = useMotionValue(0)

	useEffect(() => {
		if (textRef.current) {
			controls.stop()
			setDirection('left')
			setTextWidth(textRef.current.offsetWidth);
			setContainerWidth(textRef.current.parentElement.clientWidth);
			x.set(0)
		}
	}, [text, textRef, controls, x]);

	useMotionValueEvent(x, "change", () => {
		if (x['current'] == (-(textWidth - containerWidth + 6)) || x['current'] == 0) {
			setMask('mask-' + direction)
			setDirection((prev) => (prev === 'left' ? 'right' : 'left'))
		}
	})
	useEffect(() => {
		if (!textWidth || !containerWidth || textWidth < containerWidth) return

		const toggleDirection = async () => {
			const duration = (Math.abs(direction === 'left' ? containerWidth - x['current'] - textWidth : x['current']) / 15);

			if (direction === 'left') {
				setMask('mask-horizontal')
				await controls.start({
					x: -(textWidth - containerWidth + 6),
					transition: {
						type: 'tween',
						duration: duration,
						ease: 'linear',
						delay: x['current'] == 0 ? 1.5 : 0,
					},
				});
			} else {
				setMask('mask-horizontal')
				await controls.start({
					x: 0,
					transition: {
						type: 'tween',
						duration: duration,
						ease: 'linear',
						delay: Math.abs(x['current']) == Math.abs(textWidth - containerWidth + 6) ? 1.5 : 0,
					},
				});
			}
		};

		if (hover) {
			controls.stop()
		} else {
			toggleDirection();
		}
	}, [text, textWidth, containerWidth, hover, direction, x, controls])

	return (
		<div style={{ overflow: 'hidden', whiteSpace: 'nowrap', position: 'relative', width: '100%' }} className={'px-[3px] ' + mask}>
			<motion.div
				ref={textRef as any}
				style={{ display: 'inline-block', x }}
				animate={controls}
				onHoverStart={() => setHover(true)}
				onHoverEnd={() => setHover(false)}
			>
				{text}
			</motion.div>
	  	</div>
	);
};

export default BouncingMarquee;