import { useAppSelector } from 'state/hooks'
import { AppState } from '../index'

export function useAnyInputOpen(): boolean {
	const inputs = useAppSelector((state: AppState) => state.application.inUseInputsList)
	return inputs.length > 0
}

export function useAnyModalOpen(): boolean {
	const modals = useAppSelector((state: AppState) => state.application.inUseModalsList)
	return modals.length > 0
}

export function useCurrentId(): any {
	const currentId = useAppSelector((state: AppState) => state.application.currentId)
	return currentId
}

export function useLastSearchQuery(): any {
	const lastQuery = useAppSelector((state: AppState) => state.application.lastSearchQuery)
	return lastQuery
}

export function useCurrentSound(): any {
	const currentId = useAppSelector((state: AppState) => state.application.currentId)
	const sounds = useAppSelector((state: AppState) => state.application.sounds)

	return currentId && sounds.find(s => s.id === currentId) ? sounds.find(s => s.id === currentId) : null
}

export function usePlaylists(): any {
	const playlists = useAppSelector((state: AppState) => state.application.playlists)

	return playlists
}

export function usePlaylist(id): any {
	const playlists = useAppSelector((state: AppState) => state.application.playlists)
	const playlist = playlists?.find(s => s.id === id)

	return playlist ? playlist : null
}