import Icon from 'components/Icon'
import { useScript } from 'hooks/useScript'
import { useDispatch } from 'react-redux'
import { NavLink, useNavigate } from 'react-router-dom'
import { updatePlaylist } from 'state/application/actions'
import { usePlaylists } from 'state/application/hooks'
import { uuidToBase64Svg } from 'utils/utils'

const Playlists = () => {
	const dispatch = useDispatch()
	const playlists = usePlaylists()
	const navigate = useNavigate()
	const { getTranslationKey } = useScript()
	
	const newPlaylist = () => {
		const id = crypto.randomUUID()
		const index = playlists ? playlists.length + 1 : 1

		const data = {
			id,
			title: getTranslationKey("defaultPlaylistName", [index]),
			thumbnail: null,
			songs: []
		}

		dispatch(updatePlaylist({ data }))
		navigate('/playlist/' + id)
	}
	
	return (
		<div className='flex flex-col bg-[#121212] rounded-xl h-full overflow-hidden'>
			<div className='flex flex-row justify-between text-base font-medium mx-4 2xl:mx-5 my-1 transition-colors items-center py-1.5 2xl:py-2'>
				<div className='flex flex-row gap-3 text-sm 2xl:text-base items-center text-base-300'>
					<Icon name="playlist" className='h-4 w-4 2xl:h-5 2xl:w-5' />
					<span>{getTranslationKey("menuPlaylists")}</span>
				</div>
				<button onClick={() => newPlaylist()} className='text-base-300 hover:text-base-200 transition-colors'>
					<Icon name="plus" className='h-4 w-4 2xl:h-5 2xl:w-5' />
				</button>
			</div>

			<div className='flex flex-col px-1 mt-1 text-base-100 overflow-y-scroll scrollbar-hidden mb-1 h-full'>
				{playlists && playlists.length > 0 ? playlists.map((playlist, index) => {
					return (
						<NavLink to={`/playlist/${playlist.id}`} key={index} className={({ isActive }) => isActive ? "flex flex-row overflow-visible gap-2 2xl:gap-3 bg-[#242424] hover:bg-[#282828] p-1 rounded-md" : "flex flex-row overflow-visible gap-2 2xl:gap-3 bg-transparent hover:bg-[#202020] p-1 rounded-md"} >
							<div className='relative w-8 h-8 min-w-8 min-h-8 2xl:h-10 2xl:w-10 2xl:min-h-10 2xl:min-w-10 rounded-md'>
								<img className="absolute h-full w-full object-cover rounded-md" onError={i => i.target['src'] = uuidToBase64Svg(playlist.id)} src={playlist.thumbnail ? playlist.thumbnail : uuidToBase64Svg(playlist.id)} />
							</div>
							<div className='flex flex-col justify-evenly'>
								<span className='text-xs 2xl:text-sm'>{playlist.title}</span>
								<span className='text-xxs 2xl:text-xs text-base-400'>{getTranslationKey("playlistName")} • {playlist.songs.length} {playlist.songs.length == 1 ? getTranslationKey("playlistSongSingle") : getTranslationKey("playlistSongPlural")}</span>
							</div>
						</NavLink>
					)
				}) : (
					<button onClick={() => newPlaylist()} className='flex flex-col justify-center items-center h-full mx-4 gap-4 text-base-300/80'>
						<Icon name="plus" className='h-8 w-8' />
						<span className='text-center text-sm'>{getTranslationKey("playlistCreateFirst")}</span>
					</button>
				)}

			</div>
		</div>
	)
}

export default Playlists