import Icon from 'components/Icon'
import { useScript } from 'hooks/useScript'
import { useDispatch } from 'react-redux'
import { NavLink, useNavigate } from 'react-router-dom'
import { setLastSearchQuery } from 'state/application/actions'

const Menu = () => {
	const navigate = useNavigate()
	const dispatch = useDispatch()
	const { getTranslationKey } = useScript()
	
	const loadSearch = () => {
		dispatch(setLastSearchQuery({query: ''}))
		navigate('/search')
	}

	return (
		<div className='flex flex-col bg-[#121212] rounded-xl px-4 2xl:px-5 py-1'>
			<NavLink to="/" className='flex flex-row gap-4 2xl:gap-5 text-sm 2xl:text-base font-medium text-base-300 hover:text-base-200 transition-colors items-center py-1.5 2xl:py-2'>
				<Icon name="home" className='h-4 w-4 2xl:h-5 2xl:w-5' />
				<span>{getTranslationKey("menuHome")}</span>
			</NavLink>
			<button onClick={() => loadSearch()} className='flex flex-row gap-4 2xl:gap-5 text-sm 2xl:text-base font-medium text-base-300 hover:text-base-200 transition-colors items-center py-1.5 2xl:py-2'>
				<Icon name="search" className='h-4 w-4 2xl:h-5 2xl:w-5' />
				<span>{getTranslationKey("menuSearch")}</span>
			</button>
		</div>

	)
}

export default Menu