import { motion } from 'framer-motion';
import { useEffect, useState } from 'react';
import { fetchNui } from 'utils/fetchNui';
import { useOnClickOutside } from 'hooks/useOnClickOutside';
import { useNuiEvent } from 'hooks/useNuiEvent';
import Sidebar from 'components/Sidebar';
import { useAnyInputOpen, useAnyModalOpen } from 'state/application/hooks';
import { setCurrentId, updateSound } from 'state/application/actions';
import Player from 'components/Player';
import { useDivRef } from 'hooks/useDivRef';
import { useDispatch } from 'react-redux';
import { useScript } from 'hooks/useScript';

interface MenuProps {
	children: React.ReactNode;
}


const Layout: React.FC<MenuProps> = ({ children }) => {
	const dispatch = useDispatch()
	const inputsOpen = useAnyInputOpen()
	const modalsOpen = useAnyModalOpen()
	const parentRef = useDivRef();
	const { getTranslationKey } = useScript()

	const [panelOpen, setPanelOpen] = useState(false)
	const [displayHelpText, setDisplayHelpText] = useState(false)

	useOnClickOutside(parentRef, panelOpen ? () => fetchNui('EVO:evo_sound_player:NUI:exitMenu') : undefined);

	useNuiEvent<string>('EVO:evo_sound_player:NUI:showHelpText', () => {
		setDisplayHelpText(true)
	})

	useNuiEvent<string>('EVO:evo_sound_player:NUI:hideHelpText', () => {
		setDisplayHelpText(false)
	})
	
	useNuiEvent<string>('EVO:evo_sound_player:NUI:updateSound', (data: any) => {
		dispatch(updateSound({ data }))
	})

	useNuiEvent<string>('EVO:evo_sound_player:NUI:currentId', (data: any) => {
		if (data.currentId) {
			dispatch(setCurrentId({ currentId: data.currentId }))
		} else {
			setTimeout(() => {
				dispatch(setCurrentId({ currentId: null }))
			}, 100);
		}
	})

	useNuiEvent<string>('EVO:evo_sound_player:NUI:menuStatus', (status: any) => {
		setPanelOpen(status)
	})

	useEffect(() => {
		const handler = (e) => {
			if ((!modalsOpen && e.key == 'Escape') || (!inputsOpen && e.key == 'Backspace')) {
				fetchNui('EVO:evo_sound_player:NUI:exitMenu');
			}
		}

		window.focus()
		window.addEventListener("keyup", handler, false);

		return () => window.removeEventListener("keyup", handler, false);
	}, [panelOpen, inputsOpen, modalsOpen]);

	useEffect(() => {
		if (displayHelpText) {
			setTimeout(() => {
				setDisplayHelpText(false)
			}, 4000);
		}
	}, [displayHelpText]);

	return (
		<>
			<div className="absolute left-1/2 transform -translate-x-1/2 bottom-20 ">
				<motion.div 
					transition={{ duration: 0.1 }}
					initial={{ opacity: 0, scale: 0.9 }}
					animate={displayHelpText ? "visible" : "hidden"}
					variants={{
						visible: { opacity: 1, scale: 1 },
						hidden: { opacity: 0, scale: 0.9 },
					}}
					className='w-fit bg-base-900/80 rounded-md px-5 py-2 text-base-100'
				>
					{getTranslationKey('boomboxHelpText1')} <span className='keybind inline-flex items-center justify-center bg-base-200 box-shadow text-black rounded-md font-mono font-bold w-6 h-6 text-lg mx-0.5'>E</span> {getTranslationKey('boomboxHelpText2')}
				</motion.div>
			</div>

			<div className='flex h-screen items-center justify-end pr-10'>
				<motion.div
					ref={parentRef as any}
					transition={{ duration: 0.1 }}
					initial={{ opacity: 0, scale: 0.9 }}
					animate={panelOpen ? "visible" : "hidden"}
					variants={{
						visible: { opacity: 1, scale: 1 },
						hidden: { opacity: 0, scale: 0.9 },
					}}
					className='relative flex flex-col w-[620px] 2xl:w-[780px] max-h-[700px] bg-[#000000] rounded-2xl select-none overflow-hidden'
				>
					{/* <div className='min-h-[300px] 2xl:min-h-[400px] h-32 2xl:h-64 flex flex-row gap-1.5 2xl:gap-2'> */}
					<div className='h-[300px] 2xl:h-[400px] flex flex-row gap-1.5 2xl:gap-2'>
						<Sidebar />

						<div className='flex flex-col min-w-[67%] max-w-[67%] pt-1.5 pr-1.5 2xl:pt-2 2xl:pr-2'>
							<div className='bg-[#121212] rounded-xl h-full overflow-hidden'>
								{children}
							</div>
						</div>
					</div>

					<Player />
				</motion.div>
			</div>
		</>
	)
}

export default Layout


