import { createAction } from '@reduxjs/toolkit'


export const addInput = createAction<{ key: string}>('application/addInput')
export const removeInput = createAction<{ key: string }>('application/removeInput')
export const addModal = createAction<{ key: string}>('application/addModal')
export const removeModal = createAction<{ key: string }>('application/removeModal')
export const updateSound = createAction<{ data: any}>('application/updateSound')
export const setCurrentId = createAction<{ currentId: string }>('application/setCurrentId')
export const setLastSearchQuery = createAction<{ query: string }>('application/setLastSearchQuery')
export const setPlaylistData = createAction<{ data: any}>('application/setPlaylistData')
export const updatePlaylist = createAction<{ data: any}>('application/updatePlaylist')
export const removePlaylist = createAction<{ id: any}>('application/removePlaylist')