import { useCurrentId, useCurrentSound } from 'state/application/hooks';
import * as SliderPrimitive from "@radix-ui/react-slider"
import { formatTime } from 'utils/utils';
import { useEffect, useState } from 'react';
import { fetchNui } from 'utils/fetchNui';
import { useNuiEvent } from 'hooks/useNuiEvent';

const PlayerProgressSlider = () => {
	const currentId = useCurrentId()
	const audio = useCurrentSound()

	const [isProgressDown, setProgressDown] = useState(false)
	const [currentProgress, setCurrentProgress] = useState(0)

	useNuiEvent<string>('EVO:evo_sound_player:NUI:updateProgress', (id: any) => {
		if (id === currentId) {
			setProgressDown(false)
		}
	})


	useEffect(() => {
		setCurrentProgress(0)
	}, [currentId])

	useEffect(() => {
		if (!currentId || !audio || !audio['timestamp'] || audio['audioType'] != 'audio') return
		let progress = +audio['timestamp']

		const interval = setInterval(() => {
			if (audio['playing'] === true && isProgressDown === false) {
				progress += 0.05
				setCurrentProgress(progress)
			}
		}, 50)


		return () => clearInterval(interval)
	}, [audio, isProgressDown, currentId])

	useEffect(() => {
		if (!currentId || !audio || !audio['timestamp'] || audio['audioType'] != 'audio') return

		const progress = +audio['timestamp']

		if (audio['playing'] === false && currentProgress == 0 && progress > currentProgress) {
			setCurrentProgress(progress)
		}

	}, [currentId, audio, currentProgress])
	

	function onProgressPointerDown() {
		if (!currentId) return;

		setProgressDown(true)
	}

	function onProgressPointerUp() {
		if (!currentId || !audio) return;

		if (isProgressDown) {
			fetchNui('EVO:evo_sound_player:NUI:requestTimestamp', { id: audio.id, timestamp: currentProgress })
		}
	}

	if (!audio) {
		return null
	}

	if (audio) {
		if (audio['audioType'] == 'stream')
			return (
				<></>
			)

		return (
			<div className='flex flex-row flex-none items-center gap-1'>
				<span className='text-base-400 text-xxs 2xl:text-mxxs min-w-[35px] text-right'>{formatTime(currentProgress)}</span>
				<SliderPrimitive.Root
					className="relative flex w-full touch-none transition-all select-none items-center group rounded-xl py-2 px-1 [&[data-disabled]]:opacity-50"
					value={[currentProgress]}
					max={audio && audio['maxDuration'] ? audio['maxDuration'] : 0.0001}
					min={0}
					onPointerDown={() => onProgressPointerDown()}
					onPointerUp={() => onProgressPointerUp()}
					onValueChange={(value) => { currentId ? setCurrentProgress(value[0]) : null }}
				>
					<SliderPrimitive.Track className="relative h-[4px] w-full transition-colors grow overflow-hidden rounded-xl bg-[#4d4c4c]">
						<SliderPrimitive.Range className="absolute h-full transition-all group-hover:transition-colors bg-base-100 rounded-xl group-hover:bg-emerald-500 group-hover:[&[data-disabled]]:bg-red-300 [&[data-disabled]]:bg-red-300" />
					</SliderPrimitive.Track>

					<SliderPrimitive.Thumb className="opacity-0 group-hover:opacity-100 [&[data-disabled]]:group-hover:opacity-0 block w-3 h-3 bg-white rounded-full border-2 border-primary bg-background ring-offset-background transition-all focus-visible:outline-none" />
				</SliderPrimitive.Root>
				<span className='text-base-400 text-xxs 2xl:text-mxxs min-w-[35px] text-left'>{audio && audio['maxDuration'] ? formatTime(audio['maxDuration']) : "0:00"}</span>
			</div>
		)

	}
}

export default PlayerProgressSlider


