import Icon from 'components/Icon'
import Navigation from 'components/Navigation'
import { useScript } from 'hooks/useScript'
import React, { useEffect, useId, useRef, useState } from 'react'
import { useDispatch } from 'react-redux'
import { NavLink, useNavigate } from 'react-router-dom'
import { setLastSearchQuery, updatePlaylist } from 'state/application/actions'
import { useCurrentId, usePlaylists } from 'state/application/hooks'
import { fetchNui } from 'utils/fetchNui'
import { uuidToBase64Svg } from 'utils/utils'

const Home: React.FC = () => {
	const navigate = useNavigate()
	const dispatch = useDispatch()
	const { config, getTranslationKey } = useScript()
	const playlists = usePlaylists()
	const currentId = useCurrentId()
	const inputId = useId();

	const [searchQuery, setSearchQuery] = useState('');

	const loadSearch = () => {
		dispatch(setLastSearchQuery({ query: '' }))
		navigate('/search')
	}


	function playAudio() {
		fetchNui('EVO:evo_sound_player:NUI:playSound', { id: currentId, url: searchQuery, playlist: null })
	}


	const scrollContainerRef = useRef(null);

	useEffect(() => {
		const scrollContainer = scrollContainerRef.current;

		let isScrolling = false;
		let scrollAmount = 0;

		const smoothScroll = () => {
			if (scrollAmount !== 0) {
				scrollContainer.scrollLeft += scrollAmount * 0.05; // Adjust the multiplier for smoothness
				scrollAmount *= 0.8; // Dampen the scroll amount for smoother stop
				if (Math.abs(scrollAmount) < 0.5) {
					scrollAmount = 0;
					isScrolling = false;
				}
				requestAnimationFrame(smoothScroll);
			}
		};

		const onWheel = (event) => {
			event.preventDefault();
			scrollAmount += event.deltaY;
			if (!isScrolling) {
				isScrolling = true;
				requestAnimationFrame(smoothScroll);
			}
		};

		if (scrollContainer) {
			scrollContainer.addEventListener('wheel', onWheel);
		}

		// Cleanup the event listener on component unmount
		return () => {
			if (scrollContainer) {
				scrollContainer.removeEventListener('wheel', onWheel);
			}
		};
	}, []);


	const newPlaylist = () => {
		const id = crypto.randomUUID()
		const index = playlists ? playlists.length + 1 : 1

		const data = {
			id,
			title: getTranslationKey("defaultPlaylistName", [index]),
			thumbnail: null,
			songs: []
		}

		dispatch(updatePlaylist({ data }))
		navigate('/playlist/' + id)
	}


	return (
		<div className='flex flex-col text-base-100'>
			<div className='flex flex-row w-full h-[38px] 2xl:h-[46px] gap-3'>
				<Navigation />
				
				<div className='flex flex-row gap-2 py-1 2xl:py-1.5'>
					<button onClick={() => loadSearch()} className='relative transition-colors flex flex-row justify-center items-center gap-3 bg-indigo-500/30 hover:bg-indigo-500/60 px-4 py-1.5 2xl:px-4 2xl:py-2.5 overflow-hidden rounded-lg text-base-300 hover:text-base-200'>
						<Icon name="search" className="w-4 h-4 2xl:w-5 2xl:h-5" />
						<span className='text-sm 2xl:text-base font-medium'>{getTranslationKey("searchButton")}</span>
					</button>

					{(config && config.audioStreams && config.audioStreams.length > 0) && (
						<NavLink to='/radios' className='relative transition-colors flex flex-row justify-center items-center gap-3 bg-orange-500/30 hover:bg-orange-500/60 px-4 py-1.5 2xl:px-4 2xl:py-2.5 overflow-hidden rounded-lg text-base-300 hover:text-base-200'>
							<Icon name="radio" className="w-4 h-4 2xl:w-5 2xl:h-5" />
							<span className='text-sm 2xl:text-base font-medium'>{getTranslationKey("radioButton")}</span>
						</NavLink>
					)}
				</div>
			</div>

			{ (config && config.useSQL) && (
				<div className='flex flex-col my-3 gap-1.5 2xl:gap-2'>
					<div className='flex flex-row text-sm mx-4 text-base-200 gap-3 items-center'>
						<Icon name="playlist" className='h-4 w-4 2xl:h-5 2xl:w-5 text-base-300' />
						<span className='text-sm 2xl:text-base'>{getTranslationKey("menuPlaylists")}</span>
					</div>

					<div className='flex flex-row gap-2 overflow-x-scroll scrollbar-hidden px-4' ref={scrollContainerRef}>
						{playlists && playlists.length > 0 ? playlists.map((playlist, index) => {
							return (
								<NavLink to={`/playlist/${playlist.id}`} key={index} className={({ isActive }) => isActive ? "flex flex-row bg-[#242424] rounded-md overflow-hidden gap-3 pr-3 min-w-fit" : "flex flex-row bg-[#242424] rounded-md overflow-hidden gap-3 pr-3 w-content min-w-fit"} >
									<div className='relative w-10 h-10 2xl:h-12 2xl:w-12 rounded-md'>
										<img className="absolute h-full w-full object-cover rounded-md" onError={i => i.target['src'] = uuidToBase64Svg(playlist.id)} src={playlist.thumbnail ? playlist.thumbnail : uuidToBase64Svg(playlist.id)} />
									</div>
									<div className='flex flex-col justify-center items-center'>
										<span className='text-xs 2xl:text-sm'>{playlist.title}</span>
									</div>
								</NavLink>
							)
						}) : (
							<button onClick={() => newPlaylist()} className='flex flex-row justify-center items-center h-full my-2 gap-4 text-base-300/80 w-full'>
								<Icon name="plus" className='h-5 w-5' />
								<span className='text-center text-sm'>{getTranslationKey("playlistCreateFirst")}</span>
							</button>
						)}
					</div>
				</div>
			)}


			<div className='flex flex-col mt-8'>
				<div className='flex flex-row bg-[#242424] rounded-lg text-xs 2xl:text-sm items-center gap-1 overflow-hidden w-2/3 mx-auto'>
					<input id={inputId} onChange={(e) => setSearchQuery(e.target.value)} value={searchQuery} className='outline-none py-1.5 pl-3 2xl:py-2 2xl:pl-4 bg-transparent text-gray-100 font-normal w-full' placeholder={getTranslationKey("playPlaceholder")}></input>
					<button onClick={() => playAudio()} className='bg-green-600 pr-3.5 pl-3 py-1.5 2xl:py-2 2xl:pl-4 2xl:pr-4 text-base-100'>
						<span>{getTranslationKey("playButton")}</span>
					</button>
				</div>

				<div className='flex flex-col justify-center items-center w-3/4 mx-auto text-xxs 2xl:text-xs font-normal text-base-300 text-center mt-2'>
					<span>{getTranslationKey("playText")}</span>
				</div>
			</div>
		</div>
	)
}

export default Home