import Icon from 'components/Icon';
import { useEffect, useRef, useState } from 'react'
import { useParams, NavLink } from 'react-router-dom'
import { useCurrentId, useCurrentSound, usePlaylist, usePlaylists } from 'state/application/hooks';
import { EMPTY_IMG, formatTime, formatTime2, getBestColor, musicFallback, truncate, uuidToBase64Svg } from 'utils/utils';
import { DndContext, closestCenter } from '@dnd-kit/core';
import { arrayMove, SortableContext, useSortable, rectSortingStrategy,} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { useDispatch } from 'react-redux';
import { updatePlaylist } from 'state/application/actions';
import { restrictToVerticalAxis } from '@dnd-kit/modifiers';
import Equaliser from 'components/Equaliser';
import { fetchNui } from 'utils/fetchNui';
import PlaylistEdit from './edit';
import ColorThief from 'colorthief';
import Loader from 'components/Loader';
import PlaylistDelete from './delete';
import AddToPlaylist from 'components/AddToPlaylist';
import Navigation from 'components/Navigation';
import { useScript } from 'hooks/useScript';


const SortableItem = ({ song, i, isSelected, isPlaying, isDragging, containsSong, playSong, addToList }) => {
	const { attributes, listeners, setNodeRef, transform, transition } = useSortable({ id: song?.id });
	const { config } = useScript()
	const fallbackMusic = musicFallback()

	const style = {
		transform: CSS.Transform.toString(transform),
		transition,
	};

	return (
		<div
			ref={setNodeRef}
			style={style}
			{...attributes}
			className={`group grid grid-cols-table 2xl:grid-cols-table-large text-xs text-base-300 items-center gap-4 my-0.5 2xl:my-1 rounded-md hover:cursor-pointer overflow-hidden outline-none transition-colors ${isDragging ? 'bg-[#242424]' : 'bg-transparent hover:bg-[#242424]'}`}
			onClick={(e) => {
				e.stopPropagation();
				playSong(song);
			}}
		>
			<div className="text-right text-xs 2xl:text-sm text-base-300">
				<span className={`group-hover:hidden flex flex-row justify-end ${isSelected ? 'text-green-500' : 'text-base-200'}`}>
					{isPlaying ? (
						<Equaliser />
					) : (
						<span>{i + 1}</span>
					)}
				</span>
				<span className='group-hover:block hidden float-right'>
					<Icon name={isSelected && isPlaying ? 'pause' : 'play'} className='h-2.5 w-2.5 2xl:h-3 2xl:w-3' />
				</span>
			</div>
			<div className="flex flex-row justify-between items-center">
				<div className='px-0 py-0.5 2xl:py-0.5 flex flex-row gap-2 overflow-hidden'>
					<div className='relative h-7 w-7 2xl:h-8 2xl:w-8'>
						<img className="absolute h-full w-full object-cover rounded-md" onError={i => i.target['src'] = fallbackMusic} src={song.thumbnail ? song.thumbnail : fallbackMusic} />
					</div>
					<div className="flex flex-col justify-evenly">
						<span className={`text-xs 2xl:text-mxs leading-none whitespace-nowrap overflow-hidden ${isSelected ? 'text-green-500' : 'text-base-200'}`}>
							{truncate(song.title, 35)}
						</span>
						<div className='flex flex-row gap-1 items-center'>
							{song.explicit && <span className='bg-base-400 text-[#242424] text-xxs h-3 w-3 flex flex-row items-center justify-center rounded-[2px]'><span>E</span></span>}
							<span className="text-xxs text-base-400 leading-none whitespace-nowrap">{truncate(song.artist, 40)}</span>
						</div>
					</div>
				</div>

				{(config && config.useSQL) && (
					<button
						onClick={(e) => {
							e.stopPropagation();
							addToList(e, song);
						}}
						className='group-hover:block hidden text-base-400 hover:text-base-200'
					>
						<Icon name={containsSong ? 'circle-check' : 'circle-plus'} className={`h-3.5 w-3.5 2xl:h-4 2xl:w-4 ${containsSong ? 'text-green-500' : 'text-gray-400'}`} />
					</button>
				)}

			</div>
			<div className='w-full pr-2 text-xs'>
				<div className="group-hover:hidden block w-full pr-2 text-xs text-base-300 text-right font-mono">{formatTime(song ? song.duration : 0)}</div>
				<div {...listeners} className="group-hover:flex hidden justify-center items-center" style={{ cursor: 'grab' }}>
					<Icon name="grip" className='h-5 w-5 text-gray-400' />
				</div>
			</div>
		</div>
	);
};


const Playlist = () => {
	const { id } = useParams()
	const dispatch = useDispatch()
	const playlist = usePlaylist(id)
	const playlists = usePlaylists()
	const audio = useCurrentSound()
	const currentId = useCurrentId()
	const generativeThumbnail = uuidToBase64Svg(playlist?.id)
	const { getTranslationKey } = useScript()

	const topContentRef = useRef(null);
	const parentRef = useRef(null);
	const headerRef = useRef(null);
	const tableHeaderRef = useRef(null);

	const [isEditOpen, setIsEditOpen] = useState(false)
	const [isDeleteOpen, setIsDeleteOpen] = useState(false)
	const [isPlaylistLoaded, setPlaylistLoaded] = useState(false)
	const [opacity, setOpacity] = useState(0)
	const [isStuck, setIsStuck] = useState(false)
	const [isDragging, setIsDragging] = useState(false)
	const [img, setImg] = useState(null)
	const [bgColor, setBgColor] = useState(null)
	const [selectedSong, setSelectedSong] = useState(null)
	const [addToPlaylistOpen, setAddToPlaylistOpen] = useState(false)

	const isPlaying = audio && playlist && audio['playing'] && audio['playlist'] && audio['playlist']['isInPlaylist'] && playlist.id == audio['playlist']['playlistId']

	useEffect(() => {
		setImg(null)
		setPlaylistLoaded(false)
	}, [id])

	useEffect(() => {
		const fetchImage = async (url) => {
			try {
				const res = await fetch(url);
				if (!res.ok) {
					throw new Error('Network response was not ok');
				}

				const imageBlob = await res.blob();
				if (!imageBlob.type.includes('image')) {
					throw new Error('Invalid type');
				}

				const imageObjectURL = URL.createObjectURL(imageBlob);

				let color = await getDominantColor(imageObjectURL)

				if (!color) {
					color = await getDominantColor(generativeThumbnail)

					if (!color) {
						color = '#000000'
					}
				}

				setImg(imageObjectURL);
				setPlaylistLoaded(true);
				setBgColor(color)
			} catch (error) {
				let color = await getDominantColor(generativeThumbnail)
				if (!color)
					color = '#000000'

				setImg(null);
				setBgColor(color)
				setPlaylistLoaded(true)
			}
		};

		const fetchGenerative = async () => {
			let color = await getDominantColor(generativeThumbnail)
			if (!color)
				color = '#000000'

			setImg(null);
			setBgColor(color)
			setPlaylistLoaded(true)
		};

		if (playlist && (playlist.thumbnail != null && playlist.thumbnail != '')) {
			fetchImage(playlist.thumbnail);
		} if (playlist && (playlist.thumbnail == null || playlist.thumbnail == '')) {
			fetchGenerative()
		}
	}, [playlist, generativeThumbnail])

	useEffect(() => {
		const handleScroll = () => {
			if (headerRef.current && topContentRef.current && parentRef.current) {
				const scroll = parentRef.current.scrollTop - (topContentRef.current.offsetHeight - (headerRef.current.offsetHeight * 2))
				const opacity = scroll > 0 ? ((scroll / headerRef.current.offsetHeight) > 1 ? 1 : (scroll / headerRef.current.offsetHeight)) : 0
				setOpacity(opacity)
			}

			if (tableHeaderRef.current && parentRef.current && headerRef.current) {
				const isStuck = ((parentRef.current.getBoundingClientRect().top + headerRef.current.offsetHeight) - tableHeaderRef.current.getBoundingClientRect().top) >= 0
				setIsStuck(isStuck)
			}
		};

		const currentParent = parentRef.current

		if (currentParent) {
			currentParent.addEventListener('scroll', handleScroll);
			handleScroll();
		}

		return () => {
			if (currentParent) {
				currentParent.removeEventListener('scroll', handleScroll);
			}
		};
	}, [id, isPlaylistLoaded, headerRef, parentRef, topContentRef, tableHeaderRef]);


	function playSong(song) {
		if (song) {
			if (audio && playlist && audio['playlist'] && audio['playlist']['isInPlaylist'] && playlist.id == audio['playlist']['playlistId'] && audio['url'].includes(song.id)) {
				if (audio['playing'] == true) {
					fetchNui('EVO:evo_sound_player:NUI:requestPause', { id: currentId })
				} else {
					fetchNui('EVO:evo_sound_player:NUI:requestPlay', { id: currentId })
				}
			} else {
				fetchNui('EVO:evo_sound_player:NUI:playSound', { id: currentId, url: `https://youtube.com/watch?v=${song.id}`, playlist: playlist })
			}
		}
	}

	function requestPause() {
		if (!currentId) return;

		if (audio && playlist && audio['playlist'] && audio['playlist']['isInPlaylist'] && playlist.id == audio['playlist']['playlistId']) {
			fetchNui('EVO:evo_sound_player:NUI:requestPause', { id: audio.id })
		}
	}

	function requestPlay() {
		if (audio && playlist && audio['playlist'] && audio['playlist']['isInPlaylist'] && playlist.id == audio['playlist']['playlistId']) {
			if (!currentId) return;
			fetchNui('EVO:evo_sound_player:NUI:requestPlay', { id: audio.id })
		} else if (playlist && playlist.songs && playlist.songs.length > 0) {
			playSong(playlist.songs[0])
		}
	}

	async function getDominantColor(imgsrc) {
		const imgEl = new Image();
		imgEl.crossOrigin = 'anonymous';
		imgEl.referrerPolicy = 'no-referrer';

		return new Promise((resolve) => {
			const timer = setTimeout(() => {
				imgEl.src = '';
				resolve(null);
			}, 1000);

			imgEl.addEventListener('load', () => {
				clearTimeout(timer);
				try {
					const colorThief = new ColorThief();
					const palette = colorThief.getPalette(imgEl, 5, 1);
					const color = getBestColor(palette);
					resolve(color);
				} catch (error) {
					resolve(null);
				}
			});

			imgEl.addEventListener('error', () => {
				clearTimeout(timer);
				resolve(null);
			});

			imgEl.src = imgsrc;
		});
	}

	function addToList(e, song) {
		e.stopPropagation();

		setSelectedSong(song)
		setAddToPlaylistOpen(true)
	}

	function handleDragStart() {
		setIsDragging(true)
	}
	
	function handleDragEnd(event) {
		setIsDragging(false)
		const { active, over } = event;
		const updatedPlaylist = { ...playlist }

		if (active && over && active.id !== over.id) {
			const oldIndex = updatedPlaylist.songs.findIndex((item) => item.id === active.id);
			const newIndex = updatedPlaylist.songs.findIndex((item) => item.id === over.id);
			updatedPlaylist.songs = arrayMove(updatedPlaylist.songs, oldIndex, newIndex);
		}

		dispatch(updatePlaylist({ data: updatedPlaylist }))
	}

	return (
		<div key={id} className='relative w-full'>
			{bgColor && isPlaylistLoaded ? (
				<>
					<header ref={headerRef as any} className='absolute flex flex-row w-full h-[38px] 2xl:h-[46px]' style={{ zIndex: 1 }}>
						<div className='absolute block w-full h-full' style={{ opacity: opacity }}>
							<div className='absolute w-full h-full' style={{ zIndex: -1, backgroundColor: bgColor }}></div>
							<div className='absolute w-full h-full' style={{ zIndex: -1, backgroundColor: 'rgba(0, 0, 0, .6)' }}></div>
						</div>
						<div className='flex flex-row text-base-100 items-center gap-3' style={{ zIndex: 1 }}>
							<Navigation />

							{opacity > 0.5 && (
								<div className='flex flex-row items-center gap-2 2xl:gap-3'>
									<button onClick={() => isPlaying ? requestPause() : requestPlay()} className='h-6 w-6 2xl:h-8 2xl:w-8 rounded-full bg-green-600 flex flex-row justify-center items-center'>
										<Icon name={isPlaying ? 'pause' : 'play'} className="text-[#000000] h-2.5 w-2.5 2xl:h-3 2xl:w-3" />
									</button>
									<span className='text-base 2xl:text-lg font-semibold text-base-200 leading-none'>
										{playlist.title}
									</span>
								</div>
							)}
						</div>
					</header>

					<div ref={parentRef as any} className='relative flex flex-col text-base-100 overflow-y-scroll h-[100%] scrollbar-hidden'>
						<div ref={topContentRef as any} onClick={() => setIsEditOpen(true)} className='relative flex flex-row gap-4 hover:cursor-pointer' style={{ isolation: 'isolate' }}>
							<div className='absolute block w-full h-full' style={{ zIndex: -1, backgroundColor: bgColor }}></div>
							<div className='absolute block w-full h-full' style={{ zIndex: -1, background: 'linear-gradient(transparent 0, rgba(0, 0, 0, .5) 100%),  url(data:image/svg+xml;base64,)' }}></div>

							<div className='flex flex-row p-4 gap-4 pt-[38px] 2xl:pt-[46px] mt-1'>
								<div className='relative h-14 w-14 min-h-14 min-w-14 2xl:h-16 2xl:w-16 2xl:min-h-16 2xl:min-w-16 overflow-hidden rounded-md' style={{ boxShadow: '0 4px 60px rgba(0, 0, 0, .5)' }}>
									<img className="absolute h-full w-full object-cover rounded-md" onError={i => i.target['style'].display='none'} onLoad={i => i.target['style'].display='block'} src={generativeThumbnail ? generativeThumbnail : EMPTY_IMG} />
									{img && <img className="absolute h-full w-full object-cover rounded-md" onError={i => i.target['style'].display='none'} onLoad={i => i.target['style'].display='block'} src={img} />}
								</div>

								<div className='flex flex-col justify-evenly'>
									<span className='text-xl font-semibold text-base-200 leading-none'>{playlist.title}</span>
									<span className='text-xs text-base-300 leading-none'>{playlist.songs.length} {playlist.songs.length == 1 ? getTranslationKey('playlistSongSingle') : getTranslationKey('playlistSongPlural')} - {formatTime2(playlist ? playlist.songs.reduce((acc, song) => acc + song ? song.duration : 0, 0) : 0, getTranslationKey("timeMinute"), getTranslationKey("timeSecond"))}</span>
								</div>
							</div>
						</div>

						<div className='flex flex-col gap-1' style={{ isolation: 'isolate' }}>
							<div className='absolute w-full h-28' style={{ zIndex: -1, }}>
								<div className='absolute w-full h-[99%]' style={{ backgroundColor: bgColor }}></div>
								<div className='absolute w-full h-full' style={{ backgroundImage: 'linear-gradient(rgba(0, 0, 0, .6) 0, #121212 99%), url(data:image/svg+xml;base64,)' }}></div>
							</div>

							<div className='flex flex-row my-2 mx-4 gap-3 justify-between'>
								<button onClick={() => isPlaying ? requestPause() : requestPlay()} className='h-7 w-7 2xl:h-8 2xl:w-8 rounded-full bg-green-600 p-2 2xl:p-2'>
									<Icon name={isPlaying ? 'pause' : 'play'} className="text-[#000000]" />
								</button>
								<div className='flex flex-row gap-3'>
									<button onClick={() => setIsEditOpen(true)} className=''>
										<Icon name="edit" className="h-4 w-4 text-base-300" />
									</button>
									<button onClick={() => setIsDeleteOpen(true)} className=''>
										<Icon name="trash" className="h-4 w-4 text-base-300" />
									</button>

								</div>
							</div>

							{playlist.songs && playlist.songs.length > 0 ? (
								<>
									<div ref={tableHeaderRef as any} className={`px-3 top-[38px] 2xl:top-[46px] sticky border-b z-10 ${isStuck ? 'bg-[#202020] border-[#323232]' : 'bg-transparent border-transparent'}`}>
										<div className={`w-full grid grid-cols-table 2xl:grid-cols-table-large text-xs 2xl:text-sm text-base-300 items-center gap-4 py-0.5 2xl:py-1 border-b ${isStuck ? 'border-transparent' : 'border-[#505050]/30'}`}>
											<div className="font-normal w-full text-right">#</div>
											<div className="font-normal px-0 w-full">{getTranslationKey('playlistHeaderTitle')}</div>
											<div className="font-normal pr-2 text-center"><Icon name="clock" className='h-3 w-3 2xl:h-3.5 2xl:w-3.5 float-right' /></div>
										</div>
									</div>

									<DndContext collisionDetection={closestCenter} onDragStart={handleDragStart} onDragEnd={handleDragEnd} modifiers={[restrictToVerticalAxis]}>
										<SortableContext items={playlist.songs.map((song) => song.id)} strategy={rectSortingStrategy}>
											<div className='px-3 mb-3'>
												{playlist.songs.map((song, i) => {
													const isSelected = audio && playlist && audio['playlist'] && audio['playlist']['isInPlaylist'] && playlist.id == audio['playlist']['playlistId'] && audio['url'].includes(song.id);
													const isPlaying = audio && playlist && audio['playing'] && audio['url'].includes(song.id) && audio['playlist'] && audio['playlist']['isInPlaylist'] && playlist.id == audio['playlist']['playlistId']
													const containsSong = playlists && playlists.some(playlist => playlist.songs.findIndex(s => s.id === song.id) !== -1);

													return (
														<SortableItem
															key={song.id}
															i={i}
															song={song}
															isSelected={isSelected}
															isPlaying={isPlaying}
															isDragging={isDragging}
															containsSong={containsSong}
															playSong={playSong}
															addToList={addToList}
														/>
													);
												})}
											</div>
										</SortableContext>
									</DndContext>
								</>
							) : (
								<div className='flex flex-col justify-center items-center h-full mx-4 gap-4 mx-10 text-xs text-center text-gray-300'>
									<div className='mt-6'>
										{getTranslationKey("playlistEmptyString1")}
										<NavLink className="inline-flex flex-row justify-center items-center bg-[#282828] hover:bg-[#323232] rounded-md px-2 gap-2 mx-1" to='/search'>
											<span className='text-xs'>{getTranslationKey("playlistEmptyString2")}</span>
										</NavLink>
										{getTranslationKey("playlistEmptyString3")}
										<Icon name="circle-plus" className='inline-flex h-3.5 w-3.5 mx-1.5 text-base-300' />
										{getTranslationKey("playlistEmptyString4")}
									</div>
								</div>
							)}
						</div>
					</div>

					<PlaylistEdit playlist={playlist} isOpen={isEditOpen} setOpen={setIsEditOpen} />
					<PlaylistDelete playlist={playlist} isOpen={isDeleteOpen} setOpen={setIsDeleteOpen} />
					<AddToPlaylist song={selectedSong} isOpen={addToPlaylistOpen} setOpen={setAddToPlaylistOpen} />
				</>
			) : (
				<div className='h-[100%] w-full flex flex-col justify-center items-center gap-2 text-[#696969]'>
					<Loader size='36px' />
					<span className='text-sm font-medium text-[#999999]'>{getTranslationKey('loaderText')}</span>
				</div>
			)}
		</div>
	)
}

export default Playlist