import Icon from 'components/Icon'
import Loader from 'components/Loader'
import React, { useEffect, useId, useRef, useState } from 'react'
import { useCurrentId, useCurrentSound, useLastSearchQuery, usePlaylists } from 'state/application/hooks'
import { addSearchItem, removeAllSearchItems, removeSearchItem } from 'state/user/actions'
import { useSearchHistory } from 'state/user/hooks'
import { fetchNui } from 'utils/fetchNui'
import { formatTime, musicFallback, truncate } from 'utils/utils'
import { setLastSearchQuery } from 'state/application/actions'
import Equaliser from 'components/Equaliser'
import { useDispatch } from 'react-redux'
import AddToPlaylist from 'components/AddToPlaylist'
import Navigation from 'components/Navigation'
import { useScript } from 'hooks/useScript'
import { useNavigate } from 'react-router-dom'


function isUrl(url) {
	// Existing supported platforms
	const patterns = [
		/^https?:\/\/(www\.)?youtube\.com\/watch\?v=.+/,
		/^https?:\/\/youtube\.com\/watch\?v=.+/,
		/^https?:\/\/youtu\.be\/.+/,
		/^https?:\/\/(www\.)?youtube\.com\/embed\/.+/,
		/^https?:\/\/(www\.)?youtube\.com\/v\/.+/,
		/^https?:\/\/open\.spotify\.com\/.+\/track\/.+/,
		/^https?:\/\/soundcloud\.com\/.+\/.+/
	];

	// Audio file extensions
	const audioExtensions = [
		"mp3", "wav", "ogg", "m4a", "aac", "flac", "aiff", "alac", "webm", "opus"
	];

	// Build regex that matches any audio extension at the end
	const audioRegex = new RegExp(
		`^https?:\\/\\/.+\\.(${audioExtensions.join("|")})(\\?.*)?$`,
		"i"
	);

	// Check all patterns
	for (const p of patterns) {
		if (p.test(url)) return true;
	}

	// Check direct audio URLs
	if (audioRegex.test(url)) return true;

	return false;
}

const Search: React.FC = () => {
	const dispatch = useDispatch()
	const inputId = useId();
	const currentId = useCurrentId()
	const audio = useCurrentSound()
	const history = useSearchHistory()
	const playlists = usePlaylists()
	const lastSearchQuery = useLastSearchQuery()
	const tableRef = useRef<HTMLTableElement>(null);
	const { config, getTranslationKey } = useScript()
	const fallbackMusic = musicFallback()
	const navigate = useNavigate()

	const [searchQuery, setSearchQuery] = useState('');
	const [status, setStatus] = useState('EMPTY');
	const [result, setResult] = useState(null);
	const [currentPage, setCurrentPage] = useState(0)

	useEffect(() => {
		if (searchQuery !== lastSearchQuery) {
			setStatus('WRITING');
		}

		if (searchQuery.length === 0) {
			setStatus('EMPTY');
		}
	}, [searchQuery, lastSearchQuery]);

	useEffect(() => {
		const debounceTimeout = setTimeout(() => {
			if (searchQuery.length > 0) {
				dispatch(setLastSearchQuery({ query: searchQuery }))
			} else {
				dispatch(setLastSearchQuery({ query: '' }))
			}
		}, 500);

		return () => {
			clearTimeout(debounceTimeout);
		};
	}, [dispatch, searchQuery]);

	useEffect(() => {
		setSearchQuery(lastSearchQuery)
	}, [lastSearchQuery])

	useEffect(() => {
		if (status == 'FETCHED') {
			dispatch(addSearchItem({ search: lastSearchQuery }))
		}
	}, [status, dispatch, lastSearchQuery])

	useEffect(() => {
		if (tableRef.current) {
			tableRef.current.parentElement.scrollTop = 0
		}
	}, [tableRef])

	const fetchData = async () => {
		try {
			setStatus('FETCHING');

			const query = lastSearchQuery

			if (isUrl(query)) {
				fetchNui('EVO:evo_sound_player:NUI:playSound', { id: currentId, url: query, playlist: null })
				setSearchQuery('')
				return
			}

			const resp = await fetch(`https://api.rkss.to/v1/evo/sound/searchYoutube?query=${query}`);
			const data = await resp.json();


			setSearchQuery(current => {
				if (current != query) {
					setStatus('WRITING');
				} else {
					if (data.success && data.result && data.result.data.length > 0) {
						setStatus('FETCHED');
						setResult({
							data: [[...data.result.data]],
							hasContinuation: data.result.hasContinuation,
							queryId: data.result.queryId
						});
					} else {
						setStatus('ERROR');
					}
				}

				return current
			})

		} catch (error) {
			console.log('error on search: ', error);
		}
	};

	useEffect(() => {

		setResult(null)
		setCurrentPage(0)

		if (lastSearchQuery.length > 0) {
			fetchData();
		}
	}, [lastSearchQuery, dispatch]);

	function playSong(song) {
		if (song) {
			if (audio && audio['url'].includes(song.id)) {
				if (audio['playing'] == true) {
					fetchNui('EVO:evo_sound_player:NUI:requestPause', { id: currentId })
				} else {
					fetchNui('EVO:evo_sound_player:NUI:requestPlay', { id: currentId })
				}
			} else {
				fetchNui('EVO:evo_sound_player:NUI:playSound', { id: currentId, url: `https://youtube.com/watch?v=${song.id}`, playlist: null })
			}
		}
	}

	function searchInstant(term) {
		setSearchQuery(term)
	}

	function clearSearchTerm(e, term) {
		e.stopPropagation();
		dispatch(removeSearchItem({ search: term }))
	}

	const [selectedSong, setSelectedSong] = useState(null)
	const [addToPlaylistOpen, setAddToPlaylistOpen] = useState(false)

	function addToList(e, song) {
		e.stopPropagation();

		setSelectedSong(song)
		setAddToPlaylistOpen(true)
	}


	return (
		<div className='flex flex-col w-full h-full'>
			<div className='flex flex-row w-full h-[38px] 2xl:h-[46px] gap-2'>
				<Navigation />
				<div className='flex flex-row bg-[#242424] w-full py-1.5 2xl:py-3 rounded-full m-1 2xl:m-1.5 text-xs 2xl:text-sm items-center px-3 gap-3'>
					<Icon name="search" className="min-w-3 min-h-3 w-3 h-3 2xl:min-w-4 2xl:min-h-4 2xl:w-4 2xl:h-4 text-gray-300" />
					<input id={inputId} onChange={(e) => setSearchQuery(e.target.value)} value={searchQuery} className='outline-none bg-transparent text-gray-100 font-normal w-full' placeholder={getTranslationKey("searchPlaceHolder")}></input>
					{searchQuery.length > 0 && (
						<button onClick={() => setSearchQuery('')}>
							<Icon name="x" className="min-w-3 min-h-3 w-3 h-3 2xl:min-w-4 2xl:min-h-4 2xl:w-4 2xl:h-4 text-gray-300" />
						</button>
					)}
				</div>
			</div>

			{status == 'EMPTY' ? (
				history && history.length == 0 ? (
					<div className='h-[100%] w-full flex flex-col justify-center items-center gap-4'>
						<Icon name="search" className="h-16 w-16 text-[#242424]" />
						<span className='text-sm font-medium text-[#484848]'>{getTranslationKey("searchNoPrevText")}</span>
					</div>
				) : (
					<div className='flex flex-col px-2 gap-0.5 2xl:gap-1 py-2 h-full overflow-y-auto text-white scrollbar-hidden'>
						{history.map((term, i) => {
							return (
								<div key={i} onClick={() => searchInstant(term)} className="flex flex-row items-center gap-3 w-full justify-between py-0.5 px-2 hover:bg-[#202020] hover:cursor-pointer rounded-md">
									<div className="flex flex-row gap-3 items-center min-w-0">
										<Icon name="clock-fill" className="h-3 w-3 2xl:h-4 2xl:w-4 text-[#8c8c8c] shrink-0"/>
										<div className="text-white text-xs 2xl:text-sm text-[#ededed] truncate overflow-hidden text-ellipsis">
											{term}
										</div>
									</div>

									<button onClick={(e) => clearSearchTerm(e, term)} className="shrink-0">
										<Icon name="x" className="h-3 w-3 2xl:h-4 2xl:w-4 text-[#8c8c8c]" />
									</button>
								</div>
							)
						})}

						{history.length > 1 && (
							<button className='text-xxs 2xl:text-mxxs uppercase text-[#8c8c8c] my-2' onClick={() => dispatch(removeAllSearchItems())}>
								{getTranslationKey("searchClearAll")}
							</button>
						)}
					</div>
				)
			) : (
				status == 'WRITING' || status == 'FETCHING' ? (
					<div className='h-[100%] w-full flex flex-col justify-center items-center gap-2 text-[#696969]'>
						<Loader size='36px' />
						<span className='text-sm 2xl:text-base font-medium text-[#999999]'>{getTranslationKey("searchLoading")}</span>
					</div>
				) : (
					status != 'FETCHED' ? (
						<div className='h-[100%] w-full flex flex-col justify-center items-center gap-2 text-[#696969]'>
							<Icon name="x" className="h-12 w-12 bg-red-600 rounded-full p-1.5 text-base-200" />
							<span>Something went wrong!</span>
							<div className="flex flex-row gap-2">
								<button onClick={() => navigate(-1)} className='flex flex-row items-center justify-center gap-2 bg-[#000000]/30 rounded-md px-3 py-1 2xl:px-3 2xl:py-1.5 text-base-100'>
									<Icon name="left" className="w-3 h-3 2xl:w-4 2xl:h-4" />
									<span className='text-xs 2xl:text-sm font-medium'>go back</span>
								</button>
								<button onClick={() => fetchData()} className='flex flex-row items-center justify-center gap-2 bg-[#000000]/30 rounded-md px-3 py-1 2xl:px-3 2xl:py-1.5 text-base-100'>
									<Icon name="reload" className="w-3 h-3 2xl:w-4 2xl:h-4" />
									<span className='text-xs 2xl:text-sm font-medium'>try again</span>
								</button>
							</div>
						</div>
					) : (
						<div className='h-full overflow-y-auto text-white scrollbar-hidden'>
							<table ref={tableRef as any} className="w-full text-left text-gray-200 " cellPadding="0" cellSpacing="0">
								<thead className="text-xs text-gray-100">
									<tr className="sticky top-0 text-xs 2xl:text-sm text-base-300 bg-[#121212] z-20">
										<th scope="col" className="font-normal pl-2 pr-4 2xl:pl-3 2xl:pr-5 py-1 text-right">#</th>
										<th scope="col" className="font-normal px-0 py-1 w-full">{getTranslationKey("searchTitle")}</th>
										<th scope="col" className="font-normal px-4 py-1"><Icon name="clock" className='h-3 w-3 2xl:h-3.5 2xl:w-3.5 float-right' /></th>
									</tr>
								</thead>
								<tbody className="text-sm xl:text-md overflow-scroll">
									{result && result.data[currentPage].map((song, i) => {
										const isSelected = audio && audio['url'].includes(song.id);
										const isPlaying = audio && audio['url'].includes(song.id) && audio['playing'] == true
										const containsSong = playlists && playlists.some(playlist => playlist.songs.findIndex(s => s.id === song.id) !== -1);

										return (
											<tr onClick={() => playSong(song)} key={i} className='group hover:bg-[#242424] hover:cursor-pointer overflow-hidden'>
												<td className="pl-2 pr-4 2xl:pl-3 2xl:pr-5 py-0.5 2xl:py-1 text-right text-xs 2xl:text-sm text-base-300 min-w-[45px] 2xl:min-w-[55px]">
													<span className={`group-hover:hidden flex flex-row justify-end ${isSelected ? 'text-green-500' : 'text-base-200'}`}>
														{isPlaying ? (
															<Equaliser />
														) : (
															<span>{i + 1}</span>
														)}
													</span>
													<span className='group-hover:block hidden float-right'><Icon name={isSelected && isPlaying ? 'pause' : 'play'} className='h-2.5 w-2.5 2xl:w-3 2xl:h-3' /></span>
												</td>
												<td className="flex flex-row justify-between items-center">
													<div className='px-0 py-0.5 2xl:py-1 flex flex-row gap-2 overflow-hidden'>
														<div className='relative h-7 w-7 2xl:h-8 2xl:w-8'>
															<img className="absolute h-full w-full object-cover rounded-md" onError={i => i.target['src'] = fallbackMusic} src={song.thumbnail ? song.thumbnail : fallbackMusic} />
														</div>
														<div className="flex flex-col justify-evenly">
															<span className={`text-xs 2xl:text-mxs leading-none whitespace-nowrap overflow-hidden ${isSelected ? 'text-green-500' : 'text-base-200'}`}>{truncate(song.title, 40)}</span>
															<div className='flex flex-row gap-1 items-center'>
																{song.explicit && <span className='bg-base-400 text-[#242424] text-xxs h-3 w-3 flex flex-row items-center justify-center rounded-[2px]'><span>E</span></span>}
																<span className="text-mxxs text-base-400 whitespace-nowrap">{truncate(song.artist, 45)}</span>
															</div>
														</div>
													</div>

													{(config && config.useSQL) && (
														<button onClick={(e) => addToList(e, song)} className='group-hover:block hidden text-base-400 hover:text-base-200'>
															<Icon name={containsSong ? 'circle-check' : 'circle-plus'} className={`h-3.5 w-3.5 2xl:h-4 2xl:w-4 ${containsSong ? 'text-green-500' : 'text-gray-400'}`} />
														</button>
													)}
												</td>
												<td className="px-4 py-0.5 2xl:py-1 text-xs text-base-300 min-w-[35px] text-right font-mono">{formatTime(song ? song.duration : 0)}</td>
											</tr>
										)
									})}
								</tbody>
							</table>
						</div>
					)
				)
			)}


			<AddToPlaylist song={selectedSong} isOpen={addToPlaylistOpen} setOpen={setAddToPlaylistOpen} />
		</div>
	)
}

export default Search