import Icon from 'components/Icon';
import { useId, useState } from 'react'
import {  EMPTY_IMG, uuidToBase64Svg } from 'utils/utils';
import Modal from 'components/Modal';
import { updatePlaylist } from 'state/application/actions';
import { useDispatch } from 'react-redux';
import { useScript } from 'hooks/useScript';


const PlaylistEdit = ({playlist, isOpen, setOpen}) => {
	const thumbnail = uuidToBase64Svg(playlist?.id)
	const dispatch = useDispatch()
	const [editTitle, setEditTitle] = useState(playlist?.title)
	const [editThumbnailUrl, setEditThumbnailUrl] = useState(playlist?.thumbnail ? playlist.thumbnail : '')
	const inputTitleId = useId();
	const inputThumbnailId = useId();
	const { getTranslationKey } = useScript()

	function saveChanges() {
		const updatedPlaylist = { ...playlist }
		updatedPlaylist.title = editTitle
		updatedPlaylist.thumbnail = editThumbnailUrl

		dispatch(updatePlaylist({ data: updatedPlaylist }))
		setOpen(false)
	}


	return (
		<Modal isOpen={isOpen} onDismiss={() => setOpen(false)}>
			<div className='relative bg-[#161616] flex flex-col p-3 text-gray-300 rounded-md'>
				<div className='flex flex-row items-center gap-3'>
					<span className='font-medium text-base-200 mx-2 text-base 2xl:text-lg'>{getTranslationKey("playlistEditTitle")}</span>

					<button className='ml-auto flex flex-col items-center' onClick={() => setOpen(false)}>
						<Icon name="x" className='h-4 w-4 2xl:h-5 2xl:w-5 text-base-400'/>
						<span className="text-xxxs 2xl:text-xxs font-mono uppercase bg-[#202020] px-1 rounded-md">esc</span>
					</button>
				</div>

				<div className='flex flex-row mt-4 gap-2'>
					<div className='relative min-h-20 min-w-20 overflow-hidden rounded-md'>
						<img className="absolute h-full w-full object-cover rounded-md" src={thumbnail ? thumbnail : EMPTY_IMG} />
						<img className="absolute h-full w-full object-cover rounded-md" onError={i => i.target['style'].display='none'} onLoad={i => i.target['style'].display='block'} src={editThumbnailUrl && editThumbnailUrl.length > 0 ? editThumbnailUrl : EMPTY_IMG} />
					</div>
					
					<div className='flex flex-col justify-evenly gap-2 w-full'>
						<div className='bg-[#242424] rounded-lg text-xs items-center gap-1 overflow-hidden'>
							<input id={inputTitleId} maxLength={20} onChange={(e) => setEditTitle(e.target.value)} value={editTitle} className='outline-none py-1.5 px-3 bg-transparent text-gray-100 font-normal w-full' placeholder={getTranslationKey("playlistEditName")}></input>
						</div>

						<div className='bg-[#242424] rounded-lg text-xs items-center gap-1 overflow-hidden'>
							<input id={inputThumbnailId} onChange={(e) => setEditThumbnailUrl(e.target.value)} value={editThumbnailUrl} className='outline-none py-1.5 px-3 bg-transparent text-gray-100 font-normal w-full' placeholder={getTranslationKey("playlistEditThumbnail")}></input>
						</div>
					</div>
				</div>

				<div className='flex flex-row justify-end mt-2'>
					<button onClick={() => saveChanges()} className='text-sm bg-green-600 px-3 py-1 text-base-100 rounded-md'>
						<span>{getTranslationKey("saveButton")}</span>
					</button>
				</div>

			</div>
		</Modal>
	)
}

export default PlaylistEdit