import { createReducer } from '@reduxjs/toolkit'
import {
	addSearchItem,
	removeSearchItem,
	removeAllSearchItems
} from './actions'


export interface UserState {
	readonly searchHistory: any[]
}

const initialState: UserState = {
	searchHistory: []
}

export default createReducer(initialState, (builder) =>
	builder
		.addCase(addSearchItem, (state, { payload: { search } }) => {
			if (search.length > 0) {
				const index = state.searchHistory.indexOf(search);
		
				if (index !== -1) {
					state.searchHistory.splice(index, 1);
				}
	
				if (state.searchHistory.length >= 10) {
					state.searchHistory.pop();
				}
	
				state.searchHistory.unshift(search);
			}
		})
		.addCase(removeSearchItem, (state, { payload: { search } }) => {
			const index = state.searchHistory.indexOf(search);
    
			if (index !== -1) {
				state.searchHistory.splice(index, 1);
			}
		})
		.addCase(removeAllSearchItems, (state) => {
			state.searchHistory = []
		})
)
