import Equaliser from 'components/Equaliser'
import Icon from 'components/Icon'
import Navigation from 'components/Navigation'
import { useScript } from 'hooks/useScript'
import React from 'react'
import { useCurrentId, useCurrentSound } from 'state/application/hooks'
import { fetchNui } from 'utils/fetchNui'
import { radioFallback, truncate } from 'utils/utils'


const Radios: React.FC = () => {
	const { config, getTranslationKey } = useScript()
	const currentId = useCurrentId()
	const audio = useCurrentSound()
	const fallbackRadio = radioFallback()

	function playSong(song) {
		if (audio && audio['url'].includes(song.url)) {
			if (audio['playing'] == true) {
				fetchNui('EVO:evo_sound_player:NUI:requestPause', { id: currentId })
			} else {
				fetchNui('EVO:evo_sound_player:NUI:requestPlay', { id: currentId })
			}
		} else {
			fetchNui('EVO:evo_sound_player:NUI:playSound', { id: currentId, url: song.url, playlist: null })
		}
	}

	return (

		<div className='flex flex-col w-full h-full'>
			{config && config.audioStreams && config.audioStreams.length > 0 ? (
				<div className='h-full overflow-y-auto text-white scrollbar-hidden'>
					<div className='flex flex-row w-full h-[38px] 2xl:h-[46px]'>
						<Navigation />
						<div className='flex flex-row gap-3 text-sm 2xl:text-base items-center text-base-100 my-auto mx-4'>
							<Icon name="radio" className='h-5 w-5 2xl:h-6 2xl:w-6' />
							<span className='text-base 2xl:text-lg'>{getTranslationKey("radiosTitle")}</span>
						</div>
					</div>

					<table className="w-full text-left text-gray-200" cellPadding="0" cellSpacing="0">
						<thead className="text-xs 2xl:text-sm text-gray-100">
							<tr className="sticky top-0 text-base-300 bg-[#121212] z-20">
								<th scope="col" className="font-normal pl-2 pr-4 py-1 text-right">#</th>
								<th scope="col" className="font-normal px-0 py-1 w-full">{getTranslationKey("radiosName")}</th>
							</tr>
						</thead>
						<tbody className="text-sm xl:text-md overflow-scroll">
							{config.audioStreams.map((song, i) => {
								const isSelected = audio && audio['url'].includes(song.url);
								const isPlaying = audio && audio['url'].includes(song.url) && audio['playing'] == true

								return (
									<tr onClick={() => playSong(song)} key={i} className='group hover:bg-[#242424] hover:cursor-pointer overflow-hidden'>
										<td className="pl-2 pr-4 py-0.5 text-right text-xs 2xl:text-sm text-base-300 min-w-[45px]">
											<span className={`group-hover:hidden flex flex-row justify-end ${isSelected ? 'text-green-500' : 'text-base-200'}`}>
												{isPlaying ? (
													<Equaliser />
												) : (
													<span>{i + 1}</span>
												)}
											</span>
											<span className='group-hover:block hidden float-right'><Icon name={isSelected && isPlaying ? 'pause' : 'play'} className='h-2.5 w-2.5 2xl:h-3 2xl:w-3' /></span>
										</td>
										<td className="px-0 py-0.5 flex flex-row gap-2 overflow-hidden w-full">
											<div className='relative h-7 w-7 2xl:h-8 2xl:w-8'>
												<img className="absolute h-full w-full object-cover rounded-md" onError={i => i.target['src'] = fallbackRadio} src={song.thumbnail ? song.thumbnail : fallbackRadio} />
											</div>
											<div className="flex flex-col justify-evenly">
												<span className={`text-xs 2xl:text-mxs leading-none whitespace-nowrap overflow-hidden ${isSelected ? 'text-green-500' : 'text-base-200'}`}>{truncate(song.title ? song.title : getTranslationKey("radiosNameUnknown"), 40)}</span>
												{song.subtitle && (
													<div className='flex flex-row gap-1 items-center'>
														<span className="text-mxxs text-base-400 leading-none whitespace-nowrap">{truncate(song.subtitle, 45)}</span>
													</div>
												)}
											</div>
										</td>
									</tr>
								)
							})}
						</tbody>
					</table>
				</div>
			) : (
				<span>empty</span>
			)}

		</div>
	)
}

export default Radios