import Icon from 'components/Icon';
import { useCurrentId, useCurrentSound } from 'state/application/hooks';
import { fetchNui } from 'utils/fetchNui';
import { useNuiEvent } from 'hooks/useNuiEvent';
import { useEffect, useState } from 'react';

const PlayerControls = () => {
	const currentId = useCurrentId()
	const audio = useCurrentSound()

	const isSong = audio && audio['audioType'] == 'audio'
	const isPlaylist = audio && audio['playlist']['isInPlaylist']

	const [currentLoop, setCurrentLoop] = useState(true)
	const [currentShuffle, setCurrentShuffle] = useState(true)


	useNuiEvent<string>('EVO:evo_sound_player:NUI:updateLoop', (data: any) => {
		if (data && data.id === currentId) {
			setCurrentLoop(data.state)
		}
	})

	useNuiEvent<string>('EVO:evo_sound_player:NUI:updateShuffle', (data: any) => {
		if (data && data.id === currentId) {
			setCurrentShuffle(data.state)
		}
	})

	useEffect(() => {
		if (currentId && audio) {
			setCurrentLoop(audio['loop'])
			setCurrentShuffle(audio['shuffle'])
		}
	}, [audio, currentId])


	function requestPause() {
		if (!currentId || !audio) return;

		fetchNui('EVO:evo_sound_player:NUI:requestPause', { id: audio.id })
	}

	function requestPlay() {
		if (!currentId || !audio) return;

		fetchNui('EVO:evo_sound_player:NUI:requestPlay', { id: audio.id })
	}

	function toggleLoop() {
		if (!currentId || !audio) return;

		fetchNui('EVO:evo_sound_player:NUI:requestLoop', { id: audio.id, state: !currentLoop })
	}

	function toggleShuffle() {
		if (!currentId || !audio) return;

		fetchNui('EVO:evo_sound_player:NUI:requestShuffle', { id: audio.id, state: !currentShuffle })
	}

	function playlistPrev() {
		if (!currentId || !audio || !audio['playlist'] || !audio['playlist']['isInPlaylist'] || !audio['playlist']['playlistId']) return;

		fetchNui('EVO:evo_sound_player:NUI:requestPrevSong', { id: audio.id })
	}

	function playlistNext() {
		if (!currentId || !audio || !audio['playlist'] || !audio['playlist']['isInPlaylist'] || !audio['playlist']['playlistId']) return;

		fetchNui('EVO:evo_sound_player:NUI:requestNextSong', { id: audio.id })
	}


	return (
		<div className='flex flex-row flex-1 justify-center items-center gap-3.5 2xl:gap-5 my-auto h-full'>
			<button onClick={() => toggleShuffle()} className={`relative h-3 w-3 2xl:h-4 2xl:w-4 rounded-full ${isPlaylist ? 'cursor-pointer opacity-100' : 'cursor-default opacity-50'}`}>
				<Icon name="shuffle" className={`${isSong && isPlaylist && currentShuffle ? 'text-emerald-400' : 'text-base-300'}`} />
				{isSong && isPlaylist && currentShuffle && <div className='absolute h-[3px] w-[3px] 2xl:h-[4px] 2xl:w-[4px] rounded-full bg-emerald-400 left-1/2 transform -translate-x-1/2 -bottom-1.5' />}
			</button>
			<button onClick={() => playlistPrev()} className={`h-3 w-3 2xl:h-4 2xl:w-4 rounded-full ${isPlaylist ? 'cursor-pointer opacity-100' : 'cursor-default opacity-50'}`}>
				<Icon name="prev" className="text-base-300" />
			</button>
			<button onClick={() => audio && audio['playing'] ? requestPause() : requestPlay()} className='h-6 w-6 2xl:h-8 2xl:w-8 rounded-full bg-base-100 p-1.5 2xl:p-2'>
				<Icon name={audio && audio['playing'] ? 'pause' : 'play'} className="text-[#000000]" />
			</button>
			<button onClick={() => playlistNext()} className={`h-3 w-3 2xl:h-4 2xl:w-4 rounded-full ${isPlaylist ? 'cursor-pointer opacity-100' : 'cursor-default opacity-50'}`}>
				<Icon name="next" className="text-base-300" />
			</button>
			<button onClick={() => toggleLoop()} className={`relative h-3 w-3 2xl:h-4 2xl:w-4 rounded-full ${isSong ? 'cursor-pointer opacity-100' : 'cursor-default opacity-50'}`}>
				<Icon name="loop" className={`${isSong && currentLoop ? 'text-emerald-400' : 'text-base-300'}`} />
				{isSong && currentLoop && <div className='absolute h-[3px] w-[3px] 2xl:h-[4px] 2xl:w-[4px] rounded-full bg-emerald-400 left-1/2 transform -translate-x-1/2 -bottom-1.5' />}
			</button>
		</div>
	)
}

export default PlayerControls


