import { Context, createContext, useContext, useEffect, useState } from 'react';
import { fetchNui } from 'utils/fetchNui';
import { useNuiEvent } from './useNuiEvent';
import { setPlaylistData } from 'state/application/actions';
import { useDispatch } from 'react-redux';


interface ScriptContextType {
	config: any | null,
	locale: any | null,
	getTranslationKey: (key: string, params?: any) => string,
}

const ScriptContext = createContext<ScriptContextType>({config: null, locale: null, getTranslationKey: null});

export function ScriptProvider({ children }) {
	const dispatch = useDispatch()
	const [scriptData, setScriptData] = useState({config: null, locale: null, getTranslationKey: null});

	useNuiEvent<string>('EVO:evo_sound_player:NUI:playlistData', (data: any) => {
		dispatch(setPlaylistData({ data }))
	})
	
	useEffect(() => {
		const init = async () => {
			const res = await fetchNui('EVO:evo_sound_player:NUI:init')

			setScriptData({
				config: res['config'],
				locale: res['locale'],
				getTranslationKey
			})
		}

		init()
	// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [])

	const getTranslationKey = (key, params) => {
		let trans = scriptData.locale && scriptData.locale[key] ? scriptData.locale[key] : 'missing_trans: ' + key;

		if (params && Array.isArray(params)) {
			params.forEach(param => {
				trans = trans.replace('%s', param);
			});
		}

		return trans;
	};

	return (
		<ScriptContext.Provider value={{ ...scriptData, getTranslationKey }}>
			{children}
		</ScriptContext.Provider>
	);
}


export function useScript(): ScriptContextType {
	const context = useContext(ScriptContext as Context<ScriptContextType | undefined>)
	if (!context) throw Error('useConfig can only be used within the ConfigProvider component')
	return context
}