import Icon from 'components/Icon';
import Modal from 'components/Modal';
import { removePlaylist } from 'state/application/actions';
import { useNavigate } from 'react-router-dom';
import { useDispatch } from 'react-redux';
import { useScript } from 'hooks/useScript';


const PlaylistDelete = ({playlist, isOpen, setOpen}) => {
	const dispatch = useDispatch()
	const navigate = useNavigate()
	const { getTranslationKey } = useScript()
	
	function saveChanges() {
		if (playlist) {
			dispatch(removePlaylist({ id: playlist.id }))
			navigate('/')
			setOpen(false)
		}
	}


	return (
		<Modal isOpen={isOpen} onDismiss={() => setOpen(false)}>
			<div className='relative bg-[#161616] flex flex-col p-3 text-gray-300 rounded-md'>
				<div className='flex flex-row items-center gap-3'>
					<span className='font-medium text-base-200 mx-2 text-base 2xl:text-lg'>{getTranslationKey("playlistDeleteTitle")}</span>

					<button className='ml-auto flex flex-col items-center' onClick={() => setOpen(false)}>
						<Icon name="x" className='h-4 w-4 2xl:h-5 2xl:w-5 text-base-400'/>
						<span className="text-xxxs 2xl:text-xxs font-mono uppercase bg-[#202020] px-1 rounded-md">esc</span>
					</button>
				</div>

				<div className='flex flex-row mt-6 mb-2 text-xs justify-center gap-2'>
					{getTranslationKey("playlistDeleteWarning")}
				</div>

				<div className='flex flex-row justify-center mt-2'>
					<button onClick={() => saveChanges()} className='text-sm bg-red-600 px-3 py-1 text-base-100 rounded-md'>
						<span>{getTranslationKey("deleteButton")}</span>
					</button>
				</div>

			</div>
		</Modal>
	)
}

export default PlaylistDelete