import Icon from 'components/Icon';
import { useCurrentSound } from 'state/application/hooks';
import { musicFallback, radioFallback } from 'utils/utils';
import { useScript } from 'hooks/useScript';
import Loader from 'components/Loader';

const PlayerThumbnail = () => {
	const { config } = useScript()
	const audio = useCurrentSound()

	if (!audio) {
		return (
			<div className='h-14 w-14 min-h-14 min-w-14 2xl:h-16 2xl:w-16 2xl:min-h-16 2xl:min-w-16 p-2.5 overflow-hidden bg-indigo-500 rounded-md'>
				<Icon name="music" className="text-indigo-800" />
			</div>
		)
	}

	if (audio) {
		if (audio['audioStatus'] == 'failed') 
			return (
				<div className='h-14 w-14 min-h-14 min-w-14 2xl:h-16 2xl:w-16 2xl:min-h-16 2xl:min-w-16 p-2.5 overflow-hidden bg-red-500 rounded-md'>
					<Icon name="x" className="text-red-800" />
				</div>
			)

		if (audio['audioType'] == 'unknown' || audio['audioStatus'] != 'ready')
			return (
				<div className='h-14 w-14 min-h-14 min-w-14 2xl:h-16 2xl:w-16 2xl:min-h-16 2xl:min-w-16 p-2.5 overflow-hidden bg-indigo-500 text-indigo-800 rounded-md flex flex-row justify-center items-center '>
					<Loader width='0.5' size='32px' />
				</div>
			)

		if (audio['audioType'] == 'audio') {
			const fallbackMusic = musicFallback()

			return (
				<div className='relative h-14 w-14 min-h-14 min-w-14 2xl:h-16 2xl:w-16 2xl:min-h-16 2xl:min-w-16 overflow-hidden rounded-md'>
					<img className="absolute h-full w-full object-cover" onError={i => i.target['src'] = fallbackMusic}  src={audio && audio['metadata'] && audio['metadata']['thumbnail'] ? audio['metadata']['thumbnail'] : fallbackMusic}/>
				</div>
			)
		}

		if (audio['audioType'] == 'stream') {
			const item = config && config.audioStreams && config.audioStreams.find(o => o.url == audio['url']) ? config.audioStreams.find(o => o.url == audio['url']) : null
			const thumbnail = item && item.thumbnail ? item.thumbnail : null

			const fallbackRadio = radioFallback()


			return (
				<div className='relative h-14 w-14 min-h-14 min-w-14 2xl:h-16 2xl:w-16 2xl:min-h-16 2xl:min-w-16 overflow-hidden rounded-md'>
					<img className="absolute h-full w-full object-cover rounded-md" onError={i => i.target['src'] = fallbackRadio} src={thumbnail ? thumbnail : fallbackRadio} />
				</div>
			)
		}
	}
}

export default PlayerThumbnail


