import { useEffect } from 'react'
import { addInput, removeInput } from 'state/application/actions'
import { useScript } from './useScript'
import { useDispatch } from 'react-redux'


export function useOnInputOpen() {
	const dispatch = useDispatch();
	const { config } = useScript();

	useEffect(() => {
		const handleOnFocus = (e) => {
			if (e.target && e.target.tagName === 'INPUT') {
				dispatch(addInput({ key: e.target.id }));
			}
		};

		const handleOnBlur = (e) => {
			if (e.target && e.target.tagName === 'INPUT') {
				dispatch(removeInput({ key: e.target.id }));
			}
		};

		if (config && config.UIBetterInput) {
			document.addEventListener('mousedown', handleOnFocus);
			document.addEventListener('focus', handleOnFocus, true);
		} else {
			document.addEventListener('click', handleOnFocus);
		}

		document.addEventListener('blur', handleOnBlur, true);

		return () => {
			if (config && config.UIBetterInput) {
				document.removeEventListener('mousedown', handleOnFocus);
				document.removeEventListener('focus', handleOnFocus, true);
			} else {
				document.removeEventListener('click', handleOnFocus);
			}

			document.removeEventListener('blur', handleOnBlur, true);
		};
	}, [config, dispatch]);
}