import Icon from "components/Icon";
import Modal from "components/Modal";
import { useScript } from "hooks/useScript";
import { useDispatch } from "react-redux";
import { updatePlaylist } from "state/application/actions";
import { usePlaylists } from "state/application/hooks";
import { truncate, uuidToBase64Svg } from "utils/utils";

export default function AddToPlaylist({isOpen, setOpen, song}) {
	const dispatch = useDispatch()
	const playlists = usePlaylists()
	const { getTranslationKey } = useScript()

	const newPlaylist = () => {
		const id = crypto.randomUUID()
		const index = playlists ? playlists.length + 1 : 1

		const data = {
			id,
			title: getTranslationKey("defaultPlaylistName", [index]),
			thumbnail: null,
			songs: []
		}

		dispatch(updatePlaylist({ data }))
	}
	
	const updatePlaylistSong = (playlist) => {
		if (song) {
			const updatedPlaylist = { ...playlist }
			const index = updatedPlaylist.songs.findIndex(s => s.id === song.id);

			if (index === -1) {
				const newSong = {
					id: song.id,
					title: song.title,
					artist: song.artist,
					thumbnail: song.thumbnail,
					duration: song ? song.duration : 0,
					url: `https://youtube.com/watch?v=${song.id}`,
					isExplicit: song.explicit,
					addedAt: Date.now()
				}

				updatedPlaylist.songs =  [...updatedPlaylist.songs, newSong];
			} else {
				updatedPlaylist.songs = updatedPlaylist.songs.filter(s => s.id !== song.id)
			}


			dispatch(updatePlaylist({data: updatedPlaylist}))
		}

	}

	return (
		<Modal isOpen={isOpen} onDismiss={() => setOpen(false)}>
			<div className='relative bg-[#161616] flex flex-col p-3 text-gray-300 h-full overflow-hidden'>
				<div className='flex flex-row items-center gap-3'>
					<span className='font-medium text-base-200 mx-2 text-base 2xl:text-lg'>{getTranslationKey("playlistModalTitle")}</span>

					<button className='ml-auto flex flex-col items-center' onClick={() => setOpen(false)}>
						<Icon name="x" className='h-4 w-4 2xl:h-5 2xl:w-5 text-base-400'/>
						<span className="text-xxxs 2xl:text-xxs font-mono uppercase bg-[#202020] px-1 rounded-md">esc</span>
					</button>
				</div>

				{song && (
					<div className="flex flex-row justify-between items-center rounded-md p-1 w-fit mx-auto mt-3">
						<div className='flex flex-row gap-2 overflow-hidden'>
							<div className='relative h-7 w-7 2xl:h-8 2xl:w-8'>
								<div className='absolute h-full w-full bg-indigo-500 rounded-[7px] flex justify-center items-center'><Icon name="radio" className='h-4 w-4 text-indigo-800'/></div>
								<img className="absolute h-full w-full object-cover rounded-md" onError={e => e.target['style'].display='none'} onLoad={e => e.target['style'].display='block'} style={{display: 'none'}} src={song.thumbnail} />
							</div>
							<div className="flex flex-col justify-evenly mr-2">
								<span className={`text-xs 2xl:text-mxs leading-none whitespace-nowrap overflow-hidden text-base-200}`}>{truncate(song.title, 40)}</span>
								<div className='flex flex-row gap-1 items-center'>
									{song.explicit && <span className='bg-base-400 text-[#242424] text-xxs h-3 w-3 flex flex-row items-center justify-center rounded-[2px]'><span>E</span></span>}
									<span className="text-xxs text-base-400 leading-none whitespace-nowrap">{truncate(song.artist, 45)}</span>
								</div>
							</div>
						</div>
					</div>
				)}
				
				<hr className="my-2 mx-5 border-base-500/50" />

				<div className="flex flex-col gap-1 overflow-y-scroll h-[200px] scrollbar-hidden">
					{song && playlists && playlists.length > 0 ? playlists.map((playlist, index) => {
						const containsSong = playlist.songs.findIndex(s => s.id === song.id) != -1;

						return (
							<button onClick={() => updatePlaylistSong(playlist)} key={index} className={"flex flex-row gap-2 2xl:gap-3 bg-[#242424] hover:bg-[#303030] items-center p-1 rounded-md"}>
								<div className='relative w-8 h-8 min-w-8 min-h-8 2xl:h-10 2xl:w-10 2xl:min-h-10 2xl:min-w-10 rounded-md'>
									<img className="absolute h-full w-full object-cover rounded-md" src={uuidToBase64Svg(playlist.id)}/>
									<img className="absolute h-full w-full object-cover rounded-md" onError={e => e.target['style'].display='none'} onLoad={e => e.target['style'].display='block'} style={{display: 'none'}} src={playlist.thumbnail} />
								</div>
								<div className='flex flex-col justify-evenly items-start'>
									<span className='text-xs 2xl:text-sm'>{playlist.title}</span>
									<span className='text-xxs 2xl:text-xs text-base-400'>{getTranslationKey("playlistName")} • {playlist.songs.length} {playlist.songs.length == 1 ? 'song' : 'songs'}</span>
								</div>

								<div className="ml-auto mr-2">
									<Icon name={containsSong ? 'circle-check' : 'circle-plus'} className={`h-4 w-4 ${containsSong ? 'text-green-500' : 'text-gray-400'}`} />
								</div>
							</button>
						)
					}) : (
						<button onClick={() => newPlaylist()} className='flex flex-col justify-center items-center h-full mx-4 gap-4 text-base-300/80'>
							<Icon name="plus" className='h-8 w-8' />
							<span className='text-center text-sm'>{getTranslationKey("playlistCreateFirst")}</span>
						</button>
					)}
				</div>
				

			</div>
		</Modal>
	)
}