import { createReducer } from '@reduxjs/toolkit'
import {
	addInput,
	removeInput,
	addModal,
	removeModal,
	updateSound,
	setCurrentId,
	setLastSearchQuery,
	updatePlaylist,
	removePlaylist,
	setPlaylistData
} from './actions'
import { fetchNui } from 'utils/fetchNui'


export interface PlaylistSong {
	readonly id: string
	readonly title: string
	readonly artist: string
	readonly thumbnail: string
	readonly duration: number
	readonly url: string
	readonly isExplicit: boolean
	readonly addedAt: string
}

export interface Playlist {
	readonly id: string
	readonly title: string
	readonly thumbnail: string | null
	readonly songs: PlaylistSong[]
}

export interface ApplicationState {
	readonly inUseInputsList: any[]
	readonly inUseModalsList: any[]
	readonly sounds: any[]
	readonly currentId: string | null
	readonly searchHistory: any[]
	readonly lastSearchQuery: string
	readonly playlists: Playlist[] | null
}

const initialState: ApplicationState = {
	inUseInputsList: [],
	inUseModalsList: [],
	sounds: [],
	currentId: null,
	searchHistory: [],
	lastSearchQuery: '',
	playlists: null
}

export default createReducer(initialState, (builder) =>
	builder
		.addCase(addInput, (state, { payload: { key } }) => {
			if (state.inUseInputsList.indexOf(key) == -1) {
				state.inUseInputsList.push(key)
			}

			fetchNui('EVO:evo_sound_player:NUI:inputState', {state: state.inUseInputsList.length > 0})
		})
		.addCase(removeInput, (state, { payload: { key } }) => {
			state.inUseInputsList = state.inUseInputsList.filter(function(e) { return e !== key })

			fetchNui('EVO:evo_sound_player:NUI:inputState', {state: state.inUseInputsList.length > 0})
		})
		.addCase(addModal, (state, { payload: { key } }) => {
			if (state.inUseModalsList.indexOf(key) == -1) {
				state.inUseModalsList.push(key)
			}
		})
		.addCase(removeModal, (state, { payload: { key } }) => {
			state.inUseModalsList = state.inUseModalsList.filter(function(e) { return e !== key })
		})
		.addCase(updateSound, (state, { payload: { data } }) => {
			if (data) {
				const index = state.sounds.findIndex(s => s.id === data.id);
	
				if (index !== -1) {
					const updatedSounds = [...state.sounds];
					updatedSounds[index] = data;
					state.sounds = [...updatedSounds];
				} else {
					state.sounds = [data, ...state.sounds]
				}
			}
		})
		.addCase(setCurrentId, (state, { payload: { currentId } }) => {
			state.currentId = currentId
		})
		.addCase(setLastSearchQuery, (state, { payload: { query } }) => {
			state.lastSearchQuery = query
		})
		.addCase(updatePlaylist, (state, { payload: { data } }) => {
			if (data) {
				if (state.playlists) {
					const index = state.playlists.findIndex(s => s.id === data.id);
		
					if (index !== -1) {
						const updatedPlaylists = [...state.playlists];
						updatedPlaylists[index] = data;
						state.playlists = [...updatedPlaylists];
					} else {
						state.playlists = [...state.playlists, data]
					}
				} else {
					state.playlists = [data]
				}
	
				fetchNui('EVO:evo_sound_player:NUI:playlistsUpdated', {json: JSON.stringify(state.playlists), object: state.playlists})
			}
		})
		.addCase(setPlaylistData, (state, { payload: { data } }) => {
			state.playlists = JSON.parse(data)
		})
		.addCase(removePlaylist, (state, { payload: { id } }) => {
			if (state.playlists) {
				const index = state.playlists.findIndex(s => s.id === id);
	
				if (index !== -1) {
					state.playlists = state.playlists.filter(s => s.id !== id);
				}

				fetchNui('EVO:evo_sound_player:NUI:playlistsUpdated', {json: JSON.stringify(state.playlists), object: state.playlists})
			}
		})
)
