import { motion} from 'framer-motion';

const baseTransition = {
	duration: 1,
	ease: "easeInOut",
	repeat: Infinity,
	times: [0, 0.2, 0.5, 0.8, 1],
}

const Equaliser = () => {
	return (
		<div className='flex flex-row h-[12px] w-[12px] items-end gap-[10%]'>
			{[...Array(4).keys()].map((i) => {
				return (
					<motion.div
						key={i}
						className="w-[15%] bg-green-500"
						animate={{ height: ["10%", "50%", "100%", "10%"] }}
						transition={{ ...baseTransition,  delay: i * 0.2 }}
					/>
				)
			})}
		</div>
	);
};

export default Equaliser;