import React, { useEffect, useId, useRef } from 'react'
import { Portal } from '@reach/portal'
import { useDivRef } from 'hooks/useDivRef'
import { useOnClickOutside } from 'hooks/useOnClickOutside'
import { useDispatch } from 'react-redux'
import { addModal, removeModal } from 'state/application/actions'


interface ModalProps {
	isOpen: boolean
	onDismiss: () => void
	children?: React.ReactNode
}

export default function Modal({ isOpen, onDismiss, children }: ModalProps) {
	const id = useId()
	const ref = useDivRef();
	const contentRef = useRef<HTMLDivElement>(null);
	const dispatch = useDispatch()
	useOnClickOutside(contentRef, () => onDismiss());

	useEffect(() => {
		if (isOpen) {
			dispatch(addModal({ key: id }));
		} else {
			dispatch(removeModal({ key: id }));
		}
	}, [isOpen])

	useEffect(() => {
		const handler = (e) => {
			if (e.key == 'Escape') {
				onDismiss()
			}
		}

		window.focus()
		window.addEventListener("keyup", handler, false);

		return () => window.removeEventListener("keyup", handler, false);
	}, [isOpen]);

	return (
		isOpen && (
			<Portal containerRef={ref}>
				<div id={id} className='absolute bg-[#000000]/50 flex items-center justify-center fixed top-0 right-0 bottom-0 left-0' style={{zIndex: 2000}}>
					<div ref={contentRef} className='flex max-w-full sm:max-w-[320px] max-h-[260px] w-full sm:w-8/12 overflow-hidden rounded-md'>
						<div className='flex flex-col w-full '>
							{/* <div className='relative '> */}
							{children}
		 					{/* </div> */}
		 				</div>
					</div>
				</div>
			</Portal>
		)
	)
}